; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		bootstrap.asm
;		Purpose:	Per-program bootstrap streamed into a "resident runtime" (SHARED) compile.
;		Created:	17th July 2026
;		Reviewed: 	No
;
; ************************************************************************************************
; ************************************************************************************************
;
;		When GPC.INPUT's 4th line selects SHARED mode, a compiled program carries NO embedded
;		runtime. Instead WriteObjectCode (object.asm) streams this template as the program's first
;		255 bytes ($0801..$08FF), followed by the p-code at $0900. On RUN, BASIC's SYS 2069 enters
;		BootEntry, which:
;
;			1. checks the 4-byte magic at RTBASE, and the same 4 bytes at $A000 in bank 1 -- are
;			   the shared runtime and its bank code already resident?
;			2. if not, LOADs GPB/GPC.RT.nnn.BIN to its own home and GP1.RT.nnn.BIN into bank 1,
;			   both with secondary address 1 and both from one place, the current directory or
;			   else the root of the SD card;
;			3. enters the resident runtime at RT_ENTRY, handing it this program's p-code page,
;			   workspace start (patched per program) and workspace end, with BASIC's RAM bank
;			   selected again.
;
;		So any program brings the runtime up if it is missing, and reuses it if it is already
;		there -- one runtime on disk, loaded once in memory.
;
;		This template runs at $0801 but is STORED up in compiler space (it is globbed into the
;		application _library.asm, linked above ObjectBase). `.logical $0801 ... .here` makes 64tass
;		resolve every label inside to $08xx while placing the physical bytes in compiler space, so
;		the streamed bytes are correct for execution at $0801 after reload. object.asm streams from
;		the PHYSICAL labels ProgramBootstrap..ProgramBootstrapEnd and patches the one WS_START byte
;		at BootWSPatchOffset. The compiler's own $0801 entry (00main.header) is untouched -- this is
;		inert data the compiler only writes to disk, never executes.
;
; ************************************************************************************************

		.section code

ProgramBootstrap: 							; PHYSICAL label (compiler space) -- object.asm streams here
		.logical $0801

; ------------------------------------------------------------------------------------------------
;		BASIC stub -- byte-identical to StartBasicProgram (00main.header): 10 SYS 2069:REM GPC!
; ------------------------------------------------------------------------------------------------
		.word 	$0813 						; link -> the end-of-program marker at $0813
		.word 	10 							; line number
		.byte 	$9E 						; SYS token
		.text 	' 2069' 					; space, $0815 in decimal
		.byte 	$3A 						; ':' statement separator
		.byte 	$8F 						; REM token
		.text 	' GPC!' 					; compiler signature -- shows on LIST
		.byte 	0 							; end of line
		.word 	0 							; end of program

; ------------------------------------------------------------------------------------------------
;		SYS 2069 lands here ($0815).
; ------------------------------------------------------------------------------------------------
BootEntry:
		.cerror BootEntry != $0815, "bootstrap SYS entry is not at $0815 -- BASIC stub size drifted"
		;
		;		BANK 1 IS SELECTED FOR THE WHOLE BOOTSTRAP: the check reads $A000 and the cold path
		;		loads into it. BASIC's bank goes on the stack here and comes back before either exit,
		;		so a POKE to $A000 with no BANK still writes the bank BASIC left selected. The runtime
		;		saves and restores that bank around every bank 1 handler.
		;
		lda 	$00
		pha
		lda 	#HANDLER_BANK
		sta 	$00
		;
		;		Is the shared runtime already resident? Compare the core's 4 magic bytes at RTBASE and
		;		the same 4 at $A000, where the bank code starts, in one loop. The embedded bank code
		;		has "GE" there, so a shared program never enters it.
		;
		ldx 	#3
_BBCheck:
		lda 	RTBASE,x
		cmp 	BBMagic,x
		bne 	_BBCold
		lda 	$A000,x
		cmp 	BBMagic,x
		bne 	_BBCold
		dex
		bpl 	_BBCheck
		;
		;		The core is up. If this program uses no GPB keyword that is the whole question, but if
		;		it does it must ALSO find the handlers, and a core-only load leaves the core magic
		;		looking exactly the same. So check the second magic below RTBASE as well. Getting this
		;		wrong is not a crash here -- it is a jump into a workspace at the first GPB keyword.
		;
		;		The three per-program bytes are DATA at the end of this template, not immediates in the
		;		code. They have to be: a global label between a "_" branch and its target splits the
		;		local scope in two and the branch stops resolving -- the same trap BBTryLoad's own note
		;		describes, and it cost a build here.
		;
		lda 	BBNeedGP 					; 0 = no GPB keyword, 1 = uses them
		beq 	_BBEnter 					; WARM -- core is all this program needs
		ldx 	#3
_BBCheckGP:
		lda 	RTGPMAGIC,x
		cmp 	BBGPMagic,x
		bne 	_BBCold
		dex
		bpl 	_BBCheckGP
		bra 	_BBEnter 					; WARM -- handlers are up too
_BBCold:
		;
		;		Cold: LOAD the runtime to its own home. Try the CURRENT DIRECTORY first, then the
		;		ROOT of the SD card -- a program run from its own folder finds a runtime sitting
		;		beside it, and otherwise falls back to one copy kept at the root, so every folder
		;		on the card does not need its own 11K duplicate. A leading "/" is what addresses
		;		the root (measured on R49 from inside a subdirectory: "GPC.RT.001.BIN" is not
		;		found, "/GPC.RT.001.BIN" loads).
		;
		;		Which file: the FULL one (handlers + core, loads at RTGPBASE) if this program uses a
		;		GPB keyword, the CORE-ONLY one (loads at RTBASE) if it does not. Loading the full one
		;		always restores both magics, so a program that wanted handlers and found none simply
		;		loads over whatever core was there.
		;
		;		THEN THE BANK CODE, GP1.RT.nnn.BIN, into bank 1 from the SAME place. The three names
		;		differ only in their third character, so there is one name and that character is
		;		patched before each load. A bank code file missing beside a core that loaded is ?RT,
		;		not a search of the root: the two files are one build.
		;
		;		$A000 IS ZEROED FIRST. A core that loads beside a missing bank code file would
		;		otherwise leave an older bank code's magic standing, and the next run would enter
		;		this core with that code.
		;
		stz 	$A000
		lda 	#'C' 						; core only
		ldx 	BBNeedGP 					; the same flag the warm check reads
		beq 	_BBName
		lda 	#'B' 						; handlers and core
_BBName:
		sta 	BBName+2
		lda 	#<BBName 					; the local form of the name
		sta 	BBNameLo
		jsr 	BBLoad
		bcc 	_BBBank 					; carry clear = loaded OK
		dec 	BBNameLo 					; else the root form, one byte earlier with its "/"
		jsr 	BBLoad
		bcs 	_BBFail
_BBBank:
		lda 	#'1' 						; the bank code, from wherever the core came from
		sta 	BBName+2
		jsr 	BBLoad
		bcc 	_BBEnter
_BBFail:
		;
		;		Not on the disk. Print a short notice and drop back to BASIC READY with BASIC's bank
		;		selected again -- no runtime is up, so there is no runtime error path to take.
		;
		ldx 	#0
_BBErr:
		lda 	BBErrText,x
		beq 	_BBErrDone
		phx
		jsr 	X16_CHROUT
		plx
		inx
		bne 	_BBErr
_BBErrDone:
		pla 								; BASIC's bank, saved at BootEntry
		sta 	$00
		rts 								; return to the SYS caller -> BASIC READY

; ------------------------------------------------------------------------------------------------
;		Hand off to the resident runtime. Both cold and warm paths funnel through here, so the
;		SYS return address is preserved on the stack -- an END in the program RTSes cleanly back
;		to BASIC, exactly as an embedded program does.
; ------------------------------------------------------------------------------------------------
_BBEnter:
		;
		;		A core-only program is about to use the memory the GPB handlers occupy -- its workspace
		;		runs all the way up to RTBASE -- so it must first say so, by wiping RTGPMAGIC.
		;
		;		UNCONDITIONALLY, warm path included, and that is the whole point. It is not enough to
		;		wipe it when the core file is LOADED: the common sequence is a GPB program bringing the
		;		full runtime up, then a core-only program entering it warm and quietly overwriting the
		;		handlers, then a third program wanting them. Nothing was loaded in the middle of that,
		;		so a load-time wipe would never fire and the third program would enter handlers that
		;		had been eaten.
		;
		;		Nor is it safe to let the workspace overwrite the magic by chance: it sits in the top
		;		four bytes of that space, so whether it actually gets written depends on how much RAM
		;		the program uses. Handlers destroyed with the magic left standing is exactly the lie
		;		this check exists to prevent, so it is done on purpose rather than hoped for.
		;
		;		Cost is that the next GPB program always reloads. That is correct, not wasteful -- the
		;		handlers really were thrown away.
		;
		lda 	BBNeedGP
		bne 	_BBGo 						; a GPB program keeps them, and its workspace stops below them
		ldx 	#3
_BBZap:
		stz 	RTGPMAGIC,x 				; stz abs,x rather than lda #0 / sta abs,x -- two bytes, and
		dex 								; the padding below is where GP.BANKED's copy loop went
		bpl 	_BBZap
_BBGo:
		pla 								; BASIC's bank again, saved at BootEntry
		sta 	$00
		;
		;		HAND OVER. Three values the runtime wants, and a jmp -- and BOTH the base page
		;		and the jmp target are PATCHED, because a GP.BANKED program does not come
		;		straight here from the bootstrap.
		;
		;		A banked program carries a second bootstrap page (bootstrap2.asm) at $0900, which
		;		reads its regions in from a NAME.OVL file; its p-code starts at $0A00 rather
		;		than $0900. So WriteObjectCode patches the base page to $0A and this jmp to
		;		$0900, and the extension page does this same handover itself once it is done.
		;		A program with no region gets $09 and RT_ENTRY -- the bytes already in the
		;		template -- and its object is byte for byte what it was before any of this.
		;
		;		THE COPYING USED TO BE HERE, an 8-page loop inside this padding. It moved out to
		;		the extension page when regions became plural: the loop grew a table walk, every
		;		program was paying for it in a 255-byte template with two bytes spare, and only
		;		a banked one ever ran a single instruction of it.
		;
		;		GLOBAL LABELS, not "_" ones -- object.asm patches these operands as the template
		;		streams past and needs the addresses to do it. See BBTryLoad's own note.
		;
BBBasePage:
		lda 	#PCODE_PAGE 				; A = p-code base page -- PATCHED, $09 or $0A
		ldx 	BBWSStart 					; X = workspace start page
		ldy 	BBWSEnd 					; Y = workspace end page -- RTBASE>>8 for a program with no GPB
											; keyword, RTGPBASE>>8 for one with the handlers below it. That
											; difference is the whole point of the split: 2,560 bytes.
BBRunJmp:
		jmp 	RT_ENTRY 					; RTBASE+4 -> jmp StartRuntime -- PATCHED, both operand
											; bytes, to $0900 when there is an extension page

; ------------------------------------------------------------------------------------------------
;		LOAD a file with secondary address 1, which makes the KERNAL honour the file's own load
;		address -- RTGPBASE, RTBASE, or $A000 in the bank selected -- and ignore the one in X/Y.
;		BBTryLoad takes the name as SETNAM does, length in A and address in X/Y, and BBLoad sets
;		those three up for the runtime's name first. The regions used to come in this way too,
;		one file a bank; they arrive through bootstrap2.asm's own reader now. Logical
;		file 0 (file 1 has been seen to hang a later OPEN). Loading high never touches $0801 or the
;		p-code, so this bootstrap survives its own load. Returns carry clear on success, set if the
;		file is not there -- so the caller can just try the next name.
;
;		Sits BELOW _BBEnter deliberately: labels beginning with "_" are local to the enclosing
;		scope in 64tass, and a global label placed between _BBCold and _BBEnter would split that
;		scope in two, leaving the earlier branches referring to an _BBEnter they can no longer see.
; ------------------------------------------------------------------------------------------------
;
;		BBNameLo is the low byte of the name's address: BBName for the local form, one less for the
;		root form and its "/". Both end at BBNameEnd on the same page, so the length is BBNameEnd's
;		low byte less BBNameLo.
;
BBLoad:
		ldx 	BBNameLo 					; X = name address low
		lda 	#<BBNameEnd 				; A = name length
		sec
		sbc 	BBNameLo
		ldy 	#>BBName 					; Y = name address high
											; ...and fall straight through: A/X/Y are now exactly what
											; SETNAM wants.
BBTryLoad:
		jsr 	X16_SETNAM 					; SETNAM(length in A, name in X/Y)
		lda 	#0 							; SETLFS(logical file 0, device 8, secondary 1)
		ldx 	#8
		ldy 	#1
		jsr 	X16_SETLFS
		lda 	#0 							; LOAD into system memory
		ldx 	#<RTBASE 					; load address (ignored under SA=1, but pass the home)
		ldy 	#>RTBASE
		jmp 	X16_LOAD 					; its carry is our carry

		;
		;		TWO different numbers here, deliberately, because they answer two questions:
		;
		;		  the MAGIC carries RT_ABI -- "is a runtime already resident, and is it one I can
		;		  enter?" That is an ABI-compatibility question, so it moves only when the layout
		;		  or entry contract changes, and a resident runtime from any build of the same ABI
		;		  is safely reused.
		;
		;		  the FILE NAME carries the engine's BUILD number -- "which runtime file is mine?"
		;		  That pins a compiled program to the exact runtime it was built against.
		;
		;		Both come from a single definition (RT_ABI in common.inc, BuildNumber generated
		;		into version.asm by bumpbuild.py) rather than being spelled out here, so this copy
		;		cannot drift from the runtime's own or from what rtname.py builds.
		;
		;		NOTE the runtime build number is PINNED (rtbuild.txt), not bumped per build -- it
		;		used to bump every time, which renamed the file out from under every already
		;		compiled shared program. Move it only to force a re-pairing, and recompile them
		;		all when you do.
		;
		.cerror RT_ABI > 99, "RT_ABI > 99: the magic's last two bytes are ASCII digits - widen it here and in 00rt.header"
BBMagic:
		.text 	"GP"						; core magic, matched against RTBASE..RTBASE+1
		.byte 	(RT_ABI / 10) + '0' 		; ABI ordinal, two digits, matched against RTBASE+2..3
		.byte 	(RT_ABI - (RT_ABI / 10) * 10) + '0'
BBGPMagic:
		.text 	"GB"						; "handlers loaded too", matched against RTGPMAGIC..+1
		.byte 	(RT_ABI / 10) + '0' 		; same ordinal -- the two halves are one image and one ABI
		.byte 	(RT_ABI - (RT_ABI / 10) * 10) + '0'
		;
		;		One string, every name. The root form is the local form with a "/" in front, so the
		;		fallback costs a single byte, and the third character is patched to B, C or 1 before
		;		each load, so the three files cost one name. The name is formatted, not spelled out,
		;		so a build number of any width still comes out right.
		;
BBNameRoot:
		.text 	"/"
BBName:
		.text 	format("GPC.RT.%03d.BIN", BuildNumber) 	; third character PATCHED at run time: B, C or 1
BBNameEnd:
		.cerror (>BBNameRoot) != (>BBNameEnd), "bootstrap runtime name crosses a page -- BBLoad subtracts low bytes"
BBErrText:
		.text 	"?RT", 13, 0 				; brief -- a full line would wrap in 40 columns

;		The per-program bytes. DATA, not immediates -- see the note at the warm check. The first
;		three are written by WriteObjectCode as the template streams past; BBNameLo is working
;		state the bootstrap sets itself.
BBWSStart:
		.byte 	$FF 						; workspace start page -- PATCHED
BBWSEnd:
		.byte 	$FF 						; workspace end page (RTBASE or RTGPBASE) -- PATCHED
BBNeedGP:
		.byte 	$FF 						; 0 = no GPB keyword, 1 = uses them -- PATCHED
BBNameLo:
		.byte 	0 							; the name's low address byte, local or root form -- set on the cold path

		.fill 	$0900 - *, 0 				; pad through $08FF so the p-code starts exactly at $0900

		.here
ProgramBootstrapEnd: 						; PHYSICAL end -- (End - Start) == 255 bytes ($0801..$08FF)

BootWSPatchOffset = BBWSStart - $0801 		; offsets of the six per-program bytes within the
BootWSEndPatchOffset = BBWSEnd - $0801 		; streamed template -- object.asm builds its patch
BootGPPatchOffset = BBNeedGP - $0801 		; table from these and nothing else. The first three
BootBasePageOffset = BBBasePage+1 - $0801 	; are DATA bytes; the last three are instruction
BootRunJmpOffset = BBRunJmp+1 - $0801 		; OPERANDS -- the base page, and the jmp's two, which
											; are patched to the extension page for a banked program.

		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		bootstrap2.asm
;		Purpose:	Bootstrap EXTENSION page -- reads NAME.OVL and fills the GP.BANKED banks.
;		Created:	5th September 2026
;		Reviewed: 	No
;
; ************************************************************************************************
; ************************************************************************************************
;
;		ONLY A BANKED PROGRAM CARRIES THIS. A program with no GP.BANKED region gets the 255-byte
;		bootstrap it always got, with its p-code at $0900, and its object is byte for byte what it
;		was before this file existed. A banked program gets this page as well: the bootstrap runs
;		to its end as usual, and its closing "jmp RT_ENTRY" has been patched to come here instead.
;		This reads the regions in and then does that jmp itself.
;
;		THE REGIONS ARE NOT IN THE PROGRAM. They used to be: compiled into the object, loaded at
;		$0801 with everything else, and copied up to $A000 from there. That made a banked byte pay
;		full FILE price to arrive, and the object file has to end below the resident runtime, so the
;		eight regions the tables allowed could never have been used.
;
;		ONE FILE HOLDS ALL OF THEM, NAME.OVL, and it describes itself. Each region is a bank byte,
;		a page count, and that many pages of data, and a single BXOVLEND byte follows the last of
;		them. There is no directory, no length table and no bank map, so this page is told two
;		things about the regions: the name of the file to open, and the bank to leave selected
;		when it hands over (see BXRun). Read a header, select the bank, read the pages, repeat
;		until the marker. Which banks, in what order, and with what gaps between them are the
;		writer's business and none of this code's.
;
;		PADDING EVERY REGION UP TO A PAGE is what keeps the count in one byte. A region is capped at
;		8,188 bytes, so 32 pages covers the largest one that can exist.
;
;		IT USED TO BE A FILE A REGION, NAMED FOR ITS BANK -- PROG.009 for GP.BANKED 9 -- with $A000
;		in its own two-byte header and secondary address 1 to make the KERNAL honour it. That made
;		the loading free and the page expensive: a 32-byte bitmap saying which banks to walk, and
;		three digits poked into the name for every bank walked. All of it is now the two header
;		bytes in front of each region.
;
;		SO THE BYTES COME IN THROUGH ACPTR, one at a time, and that was measured before it was
;		written: 8,192 bytes in 17 jiffies, and the whole of GPBMODS -- 32,000 bytes in eight
;		regions -- in 75. It is slower than the eight LOADs it replaces and it is one file on the
;		disk instead of eight.
;
;		WHY IT CANNOT LIVE IN THE P-CODE. The workspace starts where the regions would have run,
;		so by the time any p-code executes those addresses are variables. The bootstrap is the
;		one moment before that, and this page is part of the bootstrap.
;
;		WHY NOT SIMPLY GROW THE BOOTSTRAP. Because then every program pays. The bootstrap ends at
;		$08FF with a handful of bytes spare; the p-code base page is handed to the runtime in A at
;		run time rather than baked into it, so a SECOND page costs a patched operand and nothing
;		else.
;
;		ONCE PER LOAD, NOT PER RUN. The workspace starts where the regions were, and a second RUN
;		would re-read a file whose contents are already in the banks. BXHigh is the guard: the
;		template ships it zero, this page makes it nonzero once the overlay is in, and a RUN that
;		finds it set goes straight to the runtime. This page is never written over -- p-code starts
;		at $0A00 and the frame stack is far above -- so the flag sticks.
;
;		A MISSING OVERLAY STOPS, and so does a truncated one, wherever it was cut. The bank holds
;		whatever the last program to use it left there, and running that is the one failure this
;		must not have. THE END MARKER IS WHAT MAKES EVERY CUT VISIBLE: a whole file reaches end of
;		file only on the marker, so end of file at the end of any page means the file is short.
;		Before the marker, the last region's last byte was the end of the file. A file cut on a
;		region boundary, or inside a region's last page, then ended the way a whole file does,
;		and it ran. The programmer owns the overlay file: nothing pairs a .OVL to the .PRG that
;		wants it, by decision, so a stale one is a stale one.
;
;		EVERY LABEL HERE IS GLOBAL AND PREFIXED BX. 64tass scopes a "_" label to the enclosing
;		global, and this file sits in the same section as bootstrap.asm; a local here would bind
;		to whatever global preceded it. See bootstrap.asm's own note.
;
; ************************************************************************************************

;
;		BXNAMEMAX and BXFILE are in common.inc, with BXOVLEND and for the same reason: the
;		runtime image reads a .OVL of its own now, so both links need both numbers and neither
;		may drift from the other. The compiler refuses a name longer than BXNAMEMAX rather than
;		truncating it -- see ObjBuildOverlayName.
;
;		BXOVLEND, the byte after the last region, is there too, and is written by the same writer
;		for both readers.
;

		.section code

ProgramBootExt: 							; PHYSICAL label -- object.asm streams from here
		.logical $0900

; ------------------------------------------------------------------------------------------------
;		Entered from the bootstrap's patched jmp, with the three values it was about to hand the
;		runtime already in the registers: A = p-code base page ($0A here), X = workspace start
;		page, Y = workspace end page. Put them down, read the overlay, pick them back up.
; ------------------------------------------------------------------------------------------------
BXEntry:
		sta 	BXBase
		stx 	BXWS
		sty 	BXWSEnd
		;
		;		A SECOND RUN HAS ITS REGIONS ALREADY. Nothing has run over them -- the workspace is
		;		untouched until the runtime starts -- so there is nothing to do but hand over.
		;
		lda 	BXHigh
		bne 	BXRun
		;
		;		The highest bank this machine has, kept for the per-region check below. MEMTOP with
		;		carry set returns the bank COUNT in A, and 0 means 256, so DEC A is the highest bank
		;		and 0 wrapping to 255 is the right answer rather than a bug.
		;
		sec
		jsr 	X16_MEMTOP
		dec 	a
		sta 	BXTop
		;
		;		Open the overlay. A PLAIN NAME, with no ",S,R" on the end of it: Box16's hypercall
		;		path opens the raw SETNAM string and would go looking for a host file actually called
		;		"NAME.OVL,S,R", while a plain name reads on x16emu, Box16 and real CMDR-DOS alike.
		;		IOSetFileName has the same note and the same reason.
		;
		lda 	BXNameLen
		ldx 	#<BXName
		ldy 	#>BXName
		jsr 	X16_SETNAM
		lda 	#BXFILE
		ldx 	#8
		ldy 	#BXFILE
		jsr 	X16_SETLFS
		jsr 	X16_OPEN
		bcs 	BXFail
		ldx 	#BXFILE 					; CHKIN TAKES THE FILE NUMBER IN X. Given it in A it
		jsr 	X16_CHKIN 					; fails, and ACPTR then waits for a talker that was
		bcs 	BXFail 						; never commanded -- a hang with nothing printed.

; ------------------------------------------------------------------------------------------------
;		One region: a bank byte, a page count, and that many pages into $A000 in that bank. Or
;		the end marker, and the overlay is in.
;
;		THE MARKER IS TESTED BEFORE THE STATUS. It is the file's last byte, so reading it sets
;		end of file, and a status test first would call a whole file short.
;
;		A BANK BYTE READ AT END OF FILE MEANS AN EMPTY FILE. A file cut between two regions has
;		already failed at the page check below, so only the first read can get here. What it
;		read is not a bank number, and selecting it would put a page of rubbish in that bank.
; ------------------------------------------------------------------------------------------------
BXRegion:
		jsr 	X16_ACPTR 					; the region's bank, or the end marker
		cmp 	#BXOVLEND
		beq 	BXAllDone
		tax 								; READST leaves X alone; ACPTR is not asked to
		jsr 	X16_READST
		bne 	BXFail 						; an empty file
		;
		;		?RAM IS PER REGION NOW, and stricter for being so: the bank actually asked for against
		;		the highest bank actually fitted, one region at a time. It used to be a single check of
		;		the top of a bitmap, made before anything loaded.
		;
		cpx 	BXTop
		beq 	BXBankOK 					; the highest bank is a legal bank
		bcs 	BXNoRam
BXBankOK:
		stx 	$00 						; the banked window is this region's from here
		jsr 	X16_ACPTR 					; and this is how many pages of it to fill
		sta 	BXPages
		;
		;		THE DESTINATION IS THE STORE'S OWN OPERAND rather than a zero page pointer. Every
		;		region starts at $A000 and only the high byte ever moves, so patching it costs three
		;		bytes where a pointer costs ten -- and it borrows no zero page from a runtime that has
		;		not started yet.
		;
		lda 	#$A0
		sta 	BXStore+2
BXPage:
		ldy 	#0
BXByteIn:
		jsr 	X16_ACPTR
BXStore:
		sta 	$A000,y 					; PATCHED, a page at a time
		iny
		bne 	BXByteIn
		inc 	BXStore+2
		;
		;		END OF FILE IS CHECKED ONCE A PAGE, and at the end of any page it is an error. A
		;		whole file reaches it only on the marker, so a cut anywhere -- inside a page, on a
		;		page boundary, on a region boundary -- is found within a page. It costs nothing
		;		inside the byte loop.
		;
		jsr 	X16_READST
		bne 	BXFail 						; the file is short
		dec 	BXPages
		bne 	BXPage
		bra 	BXRegion

; ------------------------------------------------------------------------------------------------
;		Every region is in its bank. Close, set the guard, and do the handover the bootstrap was
;		about to do when its jmp was patched to come here.
; ------------------------------------------------------------------------------------------------
BXAllDone:
		jsr 	BXClose
		inc 	BXHigh 						; a second RUN finds this set and skips the lot
BXRun:
		;
		;		WHICH BANK EACH GP.BSTR SLOT READS, into the place the runtime looks. The table is
		;		patched into this page by object.asm and copied to GPBSTRBANKS, $07F0, the top of
		;		the storage hole -- see common.inc, which has the whole of why it is there and not
		;		here. It used to be read where it lay, at the top of this page, and that address is
		;		the runtime image in an embedded program.
		;
		;		ON THE RE-RUN PATH, not inside BXAllDone, because a second RUN reaches here without
		;		reading the overlay again. Nothing clears $07F0 between the two, so this is putting
		;		back what is already there -- eleven bytes not to have to know that.
		;
		ldx 	#BSTR_MAX_BANKS-1
BXBStrCopy:
		lda 	BXBStrBanks,x
		sta 	GPBSTRBANKS,x
		dex
		bpl 	BXBStrCopy
		;
		;		THE BANK IS SET HERE, NOT LEFT WHERE THE LOADING LEFT IT. A program that falls into
		;		a GP.BANKED region from the line above reaches it by a plain GOTO, which selects no
		;		bank, so the region runs in whatever bank the program started in. That used to be
		;		the bank of the last region read, which was the last GP.BANKED region. GP.BANKEDSTR
		;		text banks are read after every region, so they took its place, and falling in ran
		;		text as p-code. The compiler patches in the last GP.BANKED region's bank instead.
		;		A second RUN, which reads nothing, now starts in the same bank as the first.
		;
		lda 	BXStartBank
		sta 	$00
		lda 	BXBase
		ldx 	BXWS
		ldy 	BXWSEnd
		jmp 	RT_ENTRY

BXClose:
		jsr 	X16_CLRCHN
		lda 	#BXFILE
		jmp 	X16_CLOSE 					; its return is this routine's return

; ------------------------------------------------------------------------------------------------
;		An overlay that is not on the disk, or is short, or wants a bank this machine does not
;		have. Say so and drop back to BASIC READY -- the SYS return address is still on the stack,
;		exactly as it is on the bootstrap's own ?RT path.
;
;		THE FILE IS CLOSED FIRST, on both paths and whether or not the OPEN got anywhere. A
;		logical file left open fails the OPEN of the next RUN, so the run after a ?OVL would say
;		?OVL as well, about a file that was there all along.
;
;		SHORT, because a full sentence would wrap in 40 columns, and because this page is spent
;		on the reader. "?OVL" and the bank number would be better, but the page has no bytes for
;		it, and what the programmer does next is the same either way: look at whether the .OVL is
;		beside the program, and whether it is the one that program was built with. ?RAM shares
;		the print loop, starting at its own text.
; ------------------------------------------------------------------------------------------------
BXNoRam:
		ldx 	#BXRamText - BXErrText
		bra 	BXErrClose
BXFail:
		ldx 	#0
BXErrClose:
		phx 								; CLOSE and CLRCHN have an X of their own
		jsr 	BXClose
		plx
BXErr:
		lda 	BXErrText,x
		beq 	BXErrDone
		phx
		jsr 	X16_CHROUT
		plx
		inx
		bne 	BXErr
BXErrDone:
		rts 								; return to the SYS caller -> BASIC READY

; ------------------------------------------------------------------------------------------------
;		The page's own state.
;
;		BXHIGH IS THE RE-RUN GUARD AND NOTHING ELSE. It was the highest bank in a bitmap that no
;		longer exists, and the name is the one thing about it that did not change. The compiler
;		does not patch it any more: the template's zero is what every program wants to ship with.
; ------------------------------------------------------------------------------------------------
BXHigh:
		.byte 	0 							; 0 = the overlay has not been read in yet
BXTop:
		.byte 	0 							; the highest bank this machine has
BXPages:
		.byte 	0 							; pages still to come in the region being read

BXNameLen:
		.byte 	0 							; PATCHED -- the overlay's name and its length, whole
BXName: 									; and complete: this page pokes nothing into it
		.fill 	BXNAMEMAX, 0

BXBase:
		.byte 	0 							; the three the runtime is waiting for
BXWS:
		.byte 	0
BXWSEnd:
		.byte 	0
BXStartBank:
		.byte 	0 							; PATCHED -- the bank selected at the handover

BXErrText:
		.text 	"?OVL", 13, 0
BXRamText:
		.text 	"?RAM", 13, 0

; ------------------------------------------------------------------------------------------------
;		WHICH RAM BANK EACH GP.BSTR SLOT READS -- one byte a slot, written by object.asm out of the
;		compiler's text-bank list, and copied to GPBSTRBANKS at BXRun.
;
;		WHEREVER IT FALLS NOW. It was pinned to the top of this page and read where it lay, which
;		is what made it free; the cost of that was an address an embedded program has its runtime
;		image at, and so no GP.BANKEDSTR in an embedded program at all. The eleven bytes of copy
;		at BXRun bought the feature in the other build. common.inc has the reasoning.
;
;		A slot with no bank stays zero and is never read: the compiler only ever emits a slot it
;		has filled in.
; ------------------------------------------------------------------------------------------------
BXBStrBanks:
		.fill 	BSTR_MAX_BANKS, 0 			; PATCHED -- sixteen slots, most of them usually zero

		.cerror * > $0A00, "bootstrap extension page has overflowed its 256 bytes"
		.fill 	$0A00 - *, 0 				; and the page is 256 bytes whatever is in it

		.here
ProgramBootExtEnd: 							; PHYSICAL end -- (End - Start) == 256 bytes

; ------------------------------------------------------------------------------------------------
;		Offsets of the bytes object.asm patches, within the streamed template.
; ------------------------------------------------------------------------------------------------
BootExtNameLenOffset = BXNameLen - $0900
BootExtNameOffset = BXName - $0900
BootExtBStrOffset = BXBStrBanks - $0900 	; the GP.BSTR slot -> bank table, BSTR_MAX_BANKS long
BootExtStartBankOffset = BXStartBank - $0900
BootExtEntry = BXEntry 						; the address the bootstrap's jmp is patched to

		.send 	code
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		control.asm
;		Purpose:	The compiler's control file, GPC.INPUT
;		Created:	14th July 2026
;		Reviewed: 	No
;
; ************************************************************************************************
; ************************************************************************************************
;
;		The compiler had SOURCE.PRG and OBJECT.PRG built into it, so the only way to point it at
;		a program was to rename files around it. It now reads GPC.INPUT, a plain text file of
;		five lines, which is what lets another program drive it:
;
;			DIR.PRG				line 1	the tokenised BASIC to compile
;			C.DIR.PRG			line 2	the object file to write
;			M.DIR.PRG			line 3	the debug map, or empty for none
;			SHARED				line 4	the compile mode, or empty for embedded
;			D.DIR.PRG			line 5	the removed-line list, or empty to keep every line
;
;		A shorter file reads its missing lines as empty.
;
;		A line ends at CR, at LF, or at anything else below a space, and an empty line is
;		skipped -- so a control file written on a CRLF host is as good as one written on the X16.
;
;		Lowercase is folded to upper. A name typed in ASCII lowercase is not the PETSCII the
;		KERNAL wants, and it is the mistake a caller will actually make; the host filesystems
;		this runs on are all case insensitive, so folding can only ever help.
;
;		There is no fallback. Without a readable GPC.INPUT the compiler says NO GPC.INPUT FILE
;		and stops, because a compiler that guesses at what it was asked to build is worse than
;		one that refuses.
;
; ************************************************************************************************

CFLineSize = 64 							; each line is a fixed 64-byte slot; the first four lines are
CFLineCount = 5 							; one contiguous 256-byte block (source, object, map, mode).
											; ReadControlFile counts lines (cfLine) and tracks CR/LF,
											; so an EMPTY line still advances -- an empty line 3 (no
											; map) must not mis-slot line 4 (the mode). Fixed slots
											; mean a single index walks the block with no pointer,
											; which matters because the KERNAL calls here are free
											; to trash zero page. Line 5 starts at offset 256, where
											; the eight-bit index is back at 0, so it has a store of
											; its own.

		.section code

; ************************************************************************************************
;
;		Read GPC.INPUT into SourceFile, ObjectFile and OptionsText.
;
;		Returns carry SET if there was no usable control file.
;
; ************************************************************************************************

ReadControlFile:
		lda 	#0 							; blank all FIVE lines. This zero-terminates each of
		tax 								; them and leaves a short control file holding empty
_RCFBlank: 									; strings rather than whatever was in memory.
		sta 	SourceFile,x 				; the first four, 256 bytes
		inx
		bne 	_RCFBlank
		ldx 	#CFLineSize
_RCFBlankList:
		sta 	DeadListFile-1,x 			; and the fifth
		dex
		bne 	_RCFBlankList

		ldy 	#ControlFile >> 8
		ldx 	#ControlFile & $FF
		jsr 	IOOpenRead
		bcs 	_RCFClose 					; no input channel -- reading is NOT harmless: CHRIN would
											; fall back to the keyboard and wait to be typed at.
		ldx 	#0 							; X = write offset (cfLine*CFLineSize + column)
		stz 	cfLine 						; current line, 0..3
		stz 	cfJustCR 					; nonzero => the previous byte was CR (to swallow a CRLF's LF)
_RCFRead:
		jsr 	IOReadByte 					; carry set at end of file
		bcs 	_RCFClose

		cmp 	#' ' 						; CR, LF, and anything else below a space, ends the line
		bcc 	_RCFEndOfLine

		stz 	cfJustCR 					; a real character clears any pending CR
		cmp 	#$C1 						; PETSCII shifted letters ($C1-$DA), what SHIFT-typing gives;
		bcc 	_RCFNotShifted 				; CBM DOS wants the UNshifted bytes in a filename, and they
		cmp 	#$DB 						; are a different character entirely, not a case.
		bcs 	_RCFNotShifted
		and 	#$7F 						; $C1-$DA -> $41-$5A
		bra 	_RCFStore
_RCFNotShifted:
		cmp 	#'a' 						; and ASCII lowercase, which is what a host text editor
		bcc 	_RCFStore 					; gives you
		cmp 	#'z'+1
		bcs 	_RCFStore
		and 	#$DF 						; $61-$7A -> $41-$5A
_RCFStore:
		pha
		txa 								; the last byte of a line is its zero terminator and is
		and 	#CFLineSize-1 				; never written to, so an over-long name is truncated
		cmp 	#CFLineSize-1 				; rather than running on into the next line.
		pla
		bcs 	_RCFRead
		ldy 	cfLine 						; line 5 is past the eight-bit index
		cpy 	#CFLineCount-1
		bcs 	_RCFStoreList
		sta 	SourceFile,x
		inx
		bra 	_RCFRead
_RCFStoreList:
		sta 	DeadListFile,x
		inx
		bra 	_RCFRead

_RCFEndOfLine: 								; A < ' '
		cmp 	#$0A 						; LF ?
		bne 	_RCFAdvance
		lda 	cfJustCR 					; an LF right after a CR (a CRLF) -> swallow it, do not
		bne 	_RCFSwallow 				; advance again; the CR already ended the line.
_RCFAdvance: 								; CR, a lone LF, or any other control ends the line
		ldy 	#0 							; remember whether this was a CR (so a following LF is eaten)
		cmp 	#$0D
		bne 	_RCFSetCR
		iny
_RCFSetCR:
		sty 	cfJustCR
		inc 	cfLine 						; advance even on an empty line -- so an empty line 3 (no
		lda 	cfLine 						; map) does not mis-slot line 4 (the mode), which the old
		cmp 	#CFLineCount 				; positional walker got wrong.
		bcs 	_RCFClose 					; captured all five lines -> stop, ignore any more
		asl 	a 							; X = cfLine * CFLineSize (64) = start of the next line,
											; modulo 256: line 5 starts at 0 in DeadListFile
		asl 	a
		asl 	a
		asl 	a
		asl 	a
		asl 	a
		tax
		bra 	_RCFRead
_RCFSwallow:
		stz 	cfJustCR
		bra 	_RCFRead

_RCFClose:
		jsr 	IOReadClose 				; close it either way. Logical file 3 is the one the source
											; is read on, so it has to be free.
		sec
		lda 	SourceFile 					; no source name means there was no usable control file:
		beq 	_RCFFail 					; missing, empty, or a first line we could not use. No object
		lda 	ObjectFile 					; name is just as useless -- nowhere to put the answer.
		beq 	_RCFFail 					; Line 4 (the mode) is optional, so it is not checked here.
		clc
_RCFFail:
		rts

; ************************************************************************************************
;
;		"GPC SQUEALING..." and the engine's own build number, then the two names, each on its
;		own labelled line -- the whole of the compiler's startup output. Three short lines so
;		nothing wraps in 40 columns.
;
;			GPC SQUEALING... V0.9.113
;			in:  <source>
;			out: <object>
;
; ************************************************************************************************

PrintWorking:
		ldx 	#WorkingText & $FF 			; "GPC SQUEALING... "
		ldy 	#WorkingText >> 8
		jsr 	PrintMessage
		ldx 	#VersionText & $FF 			; the ENGINE's build number, then CR. It lives here
		ldy 	#VersionText >> 8 			; and not in the front end because the engine is what
		jsr 	PrintMessage 				; compiles -- see scripts/bumpbuild.py
		ldx 	#InText & $FF 				; "in:  "
		ldy 	#InText >> 8
		jsr 	PrintMessage
		ldx 	#0 							; line 1, the source
		jsr 	PrintControlLine
		ldx 	#OutText & $FF 				; CR then "out: "
		ldy 	#OutText >> 8
		jsr 	PrintMessage
		ldx 	#CFLineSize 				; line 2, the object
		jsr 	PrintControlLine
		lda 	#13
		jmp 	$FFD2

; ************************************************************************************************
;
;								There was nothing to work from
;
; ************************************************************************************************

PrintNoControlFile:
		ldx 	#NoControlText & $FF
		ldy 	#NoControlText >> 8
		jmp 	PrintMessage

; ************************************************************************************************
;
;								Print the ASCIIZ string at YX
;
; ************************************************************************************************

PrintMessage:
		stx 	zTemp0
		sty 	zTemp0+1
		ldy 	#0
_PMLoop:
		lda 	(zTemp0),y
		beq 	_PMExit
		phy 								; CHROUT makes no promise about Y
		jsr 	$FFD2
		ply
		iny
		bne 	_PMLoop
_PMExit:
		rts

; ************************************************************************************************
;
;							Print the ASCIIZ control line at offset X
;
; ************************************************************************************************

PrintControlLine:
_PCLLoop:
		lda 	SourceFile,x
		beq 	_PCLExit
		phx
		jsr 	$FFD2
		plx
		inx
		bra 	_PCLLoop
_PCLExit:
		rts

; ************************************************************************************************
;
;										Fixed text
;
; ************************************************************************************************


; ************************************************************************************************
;
;		IS THE SOURCE ACTUALLY A TOKENISED BASIC PROGRAM?
;
;		The compiler reads its input as tokenised BASIC: two bytes of load address, then a
;		chain of [link][line#][tokens] records. Handed anything else it does not notice. It
;		takes the first two bytes as the load address, follows whatever the next two happen to
;		be as a link pointer, and walks off through the file -- which surfaces as a hang or a
;		disk error, saying nothing at all about the real problem.
;
;		AND IT IS AN EASY FILE TO GET WRONG, because the two spellings differ by one
;		extension: DIR.BASL is BASLOAD SOURCE, plain text, and DIR.PRG is what BASLOAD makes
;		of it. Only the second one can be compiled.
;
;		The test is the load address. An X16 BASIC program starts at $0801 -- BASIC has
;		nowhere else to put one -- so the first two bytes read $01 $08 or this is not a
;		program. That is the same invariant source/gpc/build_basl.py checks on the way out
;		of BASLOAD, so the two ends of the build agree on what a program is.
;
;		A FILE THAT WILL NOT GIVE UP TWO BYTES IS A SEPARATE ANSWER. CMDR-DOS opens a file
;		that is not there quite happily and only admits it on the first read (compiler/
;		symfile.asm learned this the same way), so 'missing' and 'empty' both arrive here as
;		a read that fails immediately -- and both are worth telling apart from a file that is
;		present but is not a program.
;
;		CC = go ahead. CS = the message is already printed, do not compile.
;
; ************************************************************************************************

ValidateSourceFile:
		ldy 	#SourceFile >> 8
		ldx 	#SourceFile & $FF
		jsr 	IOOpenRead

		;
		;		BOTH BYTES ARE READ BEFORE EITHER IS COMPARED, and that ordering is the whole
		;		difference between the two messages below. IOReadByte tests ST BEFORE it reads,
		;		so on a file that is not there the FIRST call still comes back carry clear with a
		;		zero byte -- the status only appears on the second. Comparing after the first read
		;		therefore called every missing file 'not a program', which is true but unhelpful.
		;
		;		X carries the low byte across: IOReadByte saves and restores it (phx/plx).
		;
		jsr 	IOReadByte 				; low byte of the load address
		bcs 	_VSFUnreadable
		tax 						; stash it -- IOReadByte preserves X
		jsr 	IOReadByte 				; and the high byte
		bcs 	_VSFUnreadable
		cmp 	#$08
		bne 	_VSFNotProgram
		cpx 	#$01
		bne 	_VSFNotProgram
		jsr 	IOReadClose 				; $0801, so it is a program. Close it again --
		clc 						; the compiler opens the source for itself, from
		rts 						; the top (api.asm, _CAOpenIn).


_VSFUnreadable:
		jsr 	IOReadClose
		ldx 	#NoSourceText & $FF
		ldy 	#NoSourceText >> 8
		bra 	_VSFFail
_VSFNotProgram:
		jsr 	IOReadClose
		ldx 	#NotProgramText & $FF
		ldy 	#NotProgramText >> 8
_VSFFail:
		jsr 	PrintMessage
		sec
		rts

ControlFile:
		.text 	'GPC.INPUT',0
WorkingText: 								; no CR: VersionText finishes the line, so the engine's
		.text 	'GPC SQUEALING... ',0 		; own build number is the first thing it tells you
InText: 									; uppercase: the screen boots in PETSCII upper/graphics, where
		.text 	'IN:  ',0 				; lowercase bytes are graphics glyphs, not letters
OutText: 									; the CR ends the source line and starts the object's
		.text 	13,'OUT: ',0
NoControlText:
		.text 	'NO GPC.INPUT FILE',13,0
NoSourceText:
		.text 	'SOURCE NOT FOUND OR EMPTY',13,0
NotProgramText:
		.text 	'NOT A BASIC PRG FILE',13,0

; ************************************************************************************************
;
;		The five lines of GPC.INPUT, laid out as one contiguous block -- see CFLineSize above.
;
;		These are buffers, but they are deliberately NOT in the storage section. That section is
;		a .dsection at $0400 (common.inc) and the code starts at $0801, so it is a 1K hole -- and
;		it was already full. Everything here belongs to the compiler, which lives above
;		ObjectBase and is thrown away when the object code is written, so a buffer here costs a
;		compiled program nothing at all. See the note in file-io/read.asm.
;
; ************************************************************************************************

SourceFile: 								; line 1 : what to compile
		.fill 	CFLineSize
ObjectFile: 								; line 2 : where to write it
		.fill 	CFLineSize
OptionsText: 								; line 3 : the debug map file name, or empty for none
		.fill 	CFLineSize 					; (WriteMapFile keys off its first byte)
ModeText: 									; line 4 : compile mode -- first byte 'S' (SHARED) selects
		.fill 	CFLineSize 					; the resident runtime (GPC.RT.nnn.BIN); empty/anything else
											; = the default self-contained (embedded) runtime.
DeadListFile: 								; line 5 : the removed-line list, or empty to keep every
		.fill 	CFLineSize 					; line. Past the 256-byte block, see ReadControlFile.
cfLine: 									; ReadControlFile scratch: current line, 0..4
		.fill 	1
cfJustCR: 									; ReadControlFile scratch: nonzero if the last byte was a CR
		.fill 	1

		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		deadlist.asm
;		Purpose:	Write the removed-line list GPC.INPUT line 5 names
;		Created:	13th September 2026
;		Reviewed: 	No
;		Author : 	Steven De George SR
;
; ************************************************************************************************
; ************************************************************************************************
;
;		One decimal line number a line, LF-terminated like the map, in source order. The list
;		is every line the compile left out: each line nothing reaches, and the lines a GP.ASM
;		or GP.BANKEDSTR block read for itself when its opener was left out with it. Deleting
;		exactly these lines from the source and compiling with the option off gives the same
;		object -- source/unit-tests/dcstrip.py is that test.
;
;		Pass one wrote the numbers into the edge bank as it skipped each line (deadcode.asm,
;		DCListLine). The edges were finished with at the end of pass zero, and nothing else
;		uses that bank.
;
;		An empty file when nothing was removed, including when a table filled: the file says
;		the option ran.
;
; ************************************************************************************************

		.section code

WriteDeadList:
		lda 	DeadListFile 				; no fifth line -> no list asked for
		bne 	_WDLStart
		rts
_WDLStart:
		ldx 	#DeadListFile & $FF
		ldy 	#DeadListFile >> 8
		jsr 	IOOpenWrite
		stz 	deadWalk
		stz 	deadWalk+1
_WDLLoop:
		lda 	deadWalk
		cmp 	dcListCount
		lda 	deadWalk+1
		sbc 	dcListCount+1
		bcs 	_WDLDone
		;
		;		Two bytes a number, so the index doubled. The list holds at most 4,096, so the
		;		doubled high byte is under $20 and the carry into the page add is clear.
		;
		lda 	deadWalk
		asl 	a
		sta 	zTemp0
		lda 	deadWalk+1
		rol 	a
		clc
		adc 	#DCListTable >> 8
		sta 	zTemp0+1
		.dcedge_access
		lda 	(zTemp0)
		sta 	mapValue
		ldy 	#1
		lda 	(zTemp0),y
		sta 	mapValue+1
		.dcedge_release
		jsr 	IOWriteDecimal 				; the map writer's decimal, which writes mapValue
		lda 	#10
		jsr 	IOWriteByte
		inc 	deadWalk
		bne 	_WDLLoop
		inc 	deadWalk+1
		bra 	_WDLLoop
_WDLDone:
		jmp 	IOWriteClose

deadWalk: 									; the number being written
		.fill 	2

		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;		13/09/26		Written.
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		gpscan.asm
;		Purpose:	Decide whether the compiled program uses any GP.BASIC handler.
;		Created:	18th August 2026
;
; ************************************************************************************************
; ************************************************************************************************
;
;		The GP handlers are the last thing in the runtime image, from GPBase to ObjectBase. If
;		the program never reaches any of them the whole block can be left out of the object --
;		see WriteObjectCode. This decides which.
;
;		IT ASKS THE QUESTION BY ADDRESS, NOT BY NAME OR BY TOKEN NUMBER. For each opcode in the
;		finished p-code it asks whether that opcode's handler lives at or above GPBase. That is
;		precisely the property being relied on -- "does this instruction jump into the bytes I
;		am about to discard?" -- so it cannot drift: move a handler into or out of gp-runtime/
;		and this follows it with no list to update. A token-number range check would have needed
;		the GP opcodes renumbered contiguously (an RT_ABI bump and a forced recompile of every
;		shared-mode program), and a "keyword starts with GP." check would have been a naming
;		convention pretending to be an invariant.
;
;		IT READS A BITMAP RATHER THAN THE VECTOR TABLE, and that is the only thing that changed
;		when the runtime became a separate file. It used to do the comparison itself --
;		"lda VectorTable+1,y : cmp #GPBase >> 8" -- which needed the runtime's table resident,
;		and the runtime is on disk now. But it never wanted the address, only one bit of it, so
;		genrtimage.py does the comparison against the image's own linked table at build time and
;		emits GPUsageBits. Same question, same answer, asked of 32 bytes instead of 386.
;
;		IT READS THE P-CODE RATHER THAN HOOKING THE EMITTER, which is what makes it total.
;		Tokens reach the object from two places -- the generator's T action for most keywords,
;		and hand-written X: helpers for the five that carry inline branch offsets (GP.EXITDO and
;		the four GP.SELECT commands, which cannot use T at all). Hooking emission means hooking
;		both, and means the next hand-written GP command silently opts itself out of the check.
;		Reading the code has one site and no way to miss anything.
;
;		IT USED TO WALK THE FINISHED OBJECT, stepping by MoveObjectForward so that an operand
;		byte which happens to equal a GP opcode was never read as one. There is no finished
;		object to walk any more -- pass one stores nothing and pass two's goes straight into a
;		file -- so the p-code is decoded FORWARDS instead, a byte at a time, as pass one emits
;		it. Same question, same bitmap, same instruction sizes.
;
; ************************************************************************************************

		.section code

;
;		A = token ($80..$FF), X = 0 for the plain table / 1 for the shifted one. Returns carry
;		set if that opcode's handler is at or above GPBase.
;
;		GPUsageBits is 32 bytes: 16 for the plain vectors, then 16 for the shifted, one bit per
;		opcode, bit set meaning "above the cut". The index is the token with bit 7 cleared,
;		which is exactly what the tables themselves are indexed by.
;
GPScanUsesGP:
		pha
		and 	#$7F 						; opcode index, 0..127
		lsr 	a
		lsr 	a
		lsr 	a 							; -> which byte of the map, 0..15
		cpx 	#0
		beq 	_GPSUPlain
		clc
		adc 	#16 						; the shifted half is the second 16 bytes
_GPSUPlain:
		tay
		lda 	GPUsageBits,y
		sta 	gpBits
		pla
		and 	#$07 						; -> which bit of that byte
		tax
		lda 	gpBits
_GPSUShift:
		cpx 	#0
		beq 	_GPSUTest
		lsr 	a
		dex
		bra 	_GPSUShift
_GPSUTest:
		lsr 	a 							; the wanted bit falls into the carry
		rts

gpUsed: 									; nonzero if any GP handler is reachable. Code section,
		.fill 	1 							; not storage -- it belongs to the compiler and is
gpBits: 									; thrown away with it, so it costs a compiled program
		.fill 	1 							; nothing. See the note in file-io/read.asm.

; ************************************************************************************************
;
;		THE ANSWER, WORKED OUT AS PASS ONE WRITES THE BYTES.
;
;		THE STATE SAYS WHAT THE NEXT BYTE IS -- an opcode, the token after a .shift, the length
;		of a .string or .data, or an operand to be stepped over. Only pass one runs it: pass two
;		writes the same bytes and counting them twice would prove nothing.
;
;		THE CURSOR IS CHECKED, NOT ASSUMED. A statement that fails to compile is rolled back to
;		where it began and the next one is written over it (DeferStatementToRuntime). That start
;		is an instruction boundary, so a write cursor that did not move on by one means "begin
;		again here" -- which is exactly right, and needs nothing to tell it.
;
; ************************************************************************************************

GPS_OPCODE = 0 								; the next byte is an opcode
GPS_SHIFT  = 1 								; ...the token after a .shift prefix
GPS_LENGTH = 2 								; ...the length byte of a .string or .data
GPS_SKIP   = 3 								; ...one of gpScanSkip operand bytes

GPScanReset:
		stz 	gpUsed
		stz 	gpScanState
		stz 	gpScanStop
		.set16 	gpScanAt,ObjectOrigin
		rts

GPScanByte:
		ldx 	passNumber 					; pass one settles it
		bne 	_GPSBOut
		ldx 	gpScanStop 					; ...and stops at the end marker, or as soon as the
		bne 	_GPSBOut 					; answer is yes
		pha
		lda 	objPtr 						; in step with the byte before it ?
		cmp 	gpScanAt
		bne 	_GPSBResync
		lda 	objPtr+1
		cmp 	gpScanAt+1
		beq 	_GPSBInStep
_GPSBResync:
		stz 	gpScanState 				; no -- a rolled back statement, so start again here
_GPSBInStep:
		clc
		lda 	objPtr
		adc 	#1
		sta 	gpScanAt
		lda 	objPtr+1
		adc 	#0
		sta 	gpScanAt+1
		pla
		;
		ldx 	gpScanState
		beq 	_GPSBOpcode
		cpx 	#GPS_SHIFT
		beq 	_GPSBShifted
		cpx 	#GPS_LENGTH
		beq 	_GPSBLength
		dec 	gpScanSkip 					; GPS_SKIP: one operand byte gone
		bne 	_GPSBOut
		stz 	gpScanState
_GPSBOut:
		rts
;
;		The token after a .shift. MOFSizeTable gives .shift a size of one, which is this byte,
;		so the next one is an opcode again.
;
_GPSBShifted:
		stz 	gpScanState
		ldx 	#1 							; the ShiftVectorTable half of the map
		jsr 	GPScanUsesGP
		bcc 	_GPSBOut
		bra 	_GPSBFound
;
;		The length byte of a .string or .data. A zero length leaves the next byte an opcode.
;
_GPSBLength:
		sta 	gpScanSkip
		ldx 	#GPS_SKIP
		cmp 	#0
		bne 	_GPSBState
		ldx 	#GPS_OPCODE
_GPSBState:
		stx 	gpScanState
		rts
;
;		An opcode. The ranges are MoveObjectForward's, so this steps by the same sizes the
;		runtime does, and which of them has a vector slot is GPScanUsesGP's question.
;
_GPSBOpcode:
		cmp 	#$FF 						; the end marker: the GP.ASM pool and the relocator's
		beq 	_GPSBStop 					; padding follow it and are not p-code at all
		cmp 	#$40
		bcc 	_GPSBOut 					; 00-3F: one byte, no vector slot
		cmp 	#$70
		bcc 	_GPSBOne 					; 40-6F: two bytes, no vector slot
		cmp 	#PCD_STARTBINARY
		bcc 	_GPSBOut 					; 70-7F: one byte, no vector slot
		cmp 	#PCD_STARTSYSTEM
		bcc 	_GPSBKeyword 				; 80-DC: a keyword, one byte, and it has one
		bne 	_GPSBSystem
		lda 	#GPS_SHIFT 					; DD: the token after it is the one that matters
		sta 	gpScanState
		rts

_GPSBOne:
		lda 	#1
		sta 	gpScanSkip
		lda 	#GPS_SKIP
		sta 	gpScanState
		rts

_GPSBKeyword:
		ldx 	#0 							; the VectorTable half of the map
		jsr 	GPScanUsesGP
		bcs 	_GPSBFound
		rts
;
;		DE and up: a system token, whose operand count is the table MoveObjectForward steps by.
;		255 there means a .string or .data, and the byte after the token is its length.
;
_GPSBSystem:
		pha
		cmp 	#PCD_ENDSYSTEM+1 			; defensive, exactly as the walk is: nothing above the
		bcs 	_GPSBSized 					; last system token has a vector slot
		ldx 	#0
		jsr 	GPScanUsesGP
		bcc 	_GPSBSized
		pla
		bra 	_GPSBFound
_GPSBSized:
		pla
		tay
		lda 	MOFSizeTable-PCD_STARTSYSTEM,y
		cmp 	#$FF
		beq 	_GPSBString
		tax 								; .deferror has no operand at all
		beq 	_GPSBOutFar
		sta 	gpScanSkip
		lda 	#GPS_SKIP
		sta 	gpScanState
		rts
_GPSBString:
		lda 	#GPS_LENGTH
		sta 	gpScanState
_GPSBOutFar:
		rts
;
;		Found one, so the answer is yes and nothing later can change it -- the same reasoning
;		the walk makes when it stops at the first hit.
;
_GPSBFound:
		lda 	#1
		sta 	gpUsed
_GPSBStop:
		lda 	#1
		sta 	gpScanStop
		stz 	gpScanState
		rts

gpScanState: 								; what the NEXT byte is
		.fill 	1
gpScanSkip: 								; ...and how many operand bytes are still to go past
		.fill 	1
gpScanAt: 									; where the next byte belongs, so a statement rolled
		.fill 	2 							; back can be noticed for what it is
gpScanStop: 								; nonzero once the answer is in, or the end marker seen
		.fill 	1

		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;		30/08/26		Vector table read replaced by the generated GPUsageBits bitmap, so the
;						runtime image no longer has to be resident to answer the question.
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		memreport.asm
;		Purpose:	Report what the compiled program costs and what it has left.
;		Created:	18th August 2026
;
; ************************************************************************************************
; ************************************************************************************************
;
;		Printed after OK, a line at a time:
;
;			OK LOW CODE 11776, SHARED GPBASIC
;			RUNTIME 13567 									embedded only
;			LOW FREE 9728, FRAME STACK 2048
;			LINES 2744
;			DEAD CODE:  202 LINES REMOVED, 1413 BYTES SAVED 		only with removal on
;			BANK   7 CODE  3328 USED  4864 FREE 				a line a bank, only if any
;			BANK  12 TEXT  3840 USED  4352 FREE
;			TOTAL BANKS 2, 7168 USED
;
;		LOW CODE  the p-code that stays in low memory: FreeMemory up to objPtr, or up to
;				gpBankStart once a GP.BANKED region or GP.BANKEDSTR text has gone into a bank,
;				because those bytes load into their banks. It is the length PrepareObjectCode
;				rounds up to pages (compiler/object.asm), so where the p-code lands, plus those
;				pages, plus the frame stack, is where the workspace starts.
;		SHARED	the program loads a resident runtime file; EMBEDDED, it carries its own.
;		GPBASIC	the GP.BASIC handlers are in: shared, the program asks for GPB.RT.nnn.BIN;
;				embedded, some keyword reached the handler block and the whole runtime went in.
;				CORE when they are not: GPC.RT.nnn.BIN, or the block dropped (gpscan.asm).
;		RUNTIME	the runtime bytes an embedded object carries.
;		LOW FREE  what is left for variables, strings and arrays -- workspace start up to $9F00
;				embedded, or up to the resident runtime in shared mode. This is the number that
;				actually runs out.
;		FRAME STACK  the gap between the p-code and the workspace, for GOSUB and FOR frames.
;				Reserved, so LOW FREE does not include it.
;		LINES	the source lines the last pass read, whichever reader read them -- the main loop,
;				or GP.ASM and GP.BANKEDSTR pulling in their own bodies -- less the ones dead-code
;				removal left out, which were read past and not compiled.
;		DEAD CODE  only when GPC.INPUT line 5 turned removal on: the lines left out, then the
;				bytes that saved -- pass zero's length less pass one's. Four wide each.
;		BANK	one line per GP.BANKED region and GP.BANKEDSTR text bank -- see PrintBankReport.
;
;		All of it is computed here rather than stashed by WriteObjectCode: objPtr, gpBankStart,
;		newWorkspacePage and runtimeEndPage all survive it unchanged, and WriteMapFile touches
;		none of them, so there is nothing to preserve and no second copy to fall out of step.
;
; ************************************************************************************************

		.section code

PrintMemoryReport:
		;
		;		LOW CODE -- the p-code length, less anything that went into a bank.
		;
		ldx 	#CodeText & $FF
		ldy 	#CodeText >> 8
		jsr 	PrintMessage
		lda 	objPtr
		ldy 	objPtr+1
		ldx 	gpBankActive
		beq 	_PMRLowEnd
		lda 	gpBankStart 				; the lowest banked byte, page aligned
		ldy 	gpBankStart+1
_PMRLowEnd:
		sec
		sbc 	#ObjectOrigin & $FF
		sta 	reportValue
		tya
		sbc 	#ObjectOrigin >> 8
		sta 	reportValue+1
		jsr 	PrintDecimal
		;
		;		SHARED or EMBEDDED, then whether the GP.BASIC handlers are in.
		;
		ldx 	#EmbeddedText & $FF
		ldy 	#EmbeddedText >> 8
		lda 	ModeText
		cmp 	#'S'
		bne 	_PMRMode
		ldx 	#SharedText & $FF
		ldy 	#SharedText >> 8
_PMRMode:
		jsr 	PrintMessage
		ldx 	#CoreText & $FF
		ldy 	#CoreText >> 8
		lda 	gpUsed
		ldx 	ModeText 					; an EMBEDDED program with a region carries them whether it
		cpx 	#'S' 						; calls one or not: the p-code run page has to be a constant
		beq 	_PMRWhich 					; and that is what makes it one -- see PrepareObjectCode.
		ora 	gpBankActive 				; A shared program patches its bootstrap from gpUsed alone
_PMRWhich:
		beq 	_PMRHandlers
		ldx 	#GPBasicText & $FF
		ldy 	#GPBasicText >> 8
_PMRHandlers:
		jsr 	PrintMessage
		lda 	#13
		jsr 	$FFD2
		;
		;		RUNTIME -- embedded only. A shared program carries none.
		;
		lda 	ModeText
		cmp 	#'S'
		beq 	_PMRFree
		ldx 	#RuntimeText & $FF
		ldy 	#RuntimeText >> 8
		jsr 	PrintMessage
		sec
		lda 	#0 							; the runtime as written: cut - RTIMG_LOAD. The label
		sbc 	#RTIMG_LOAD & $FF 			; used to be StartBasicProgram, which lives in the
		sta 	reportValue 				; runtime image and so is no longer linked here --
		lda 	runtimeEndPage 				; genrtimage.py hands the address across instead.
		sbc 	#RTIMG_LOAD >> 8
		sta 	reportValue+1
		jsr 	PrintDecimal
		lda 	#13
		jsr 	$FFD2
		;
		;		LOW FREE -- workspace start up to the ceiling, which differs by mode. Both ends are
		;		page numbers, so the difference is the high byte of the answer and the low byte
		;		is always zero. The frame stack is pages too.
		;
_PMRFree:
		ldx 	#FreeText & $FF
		ldy 	#FreeText >> 8
		jsr 	PrintMessage
		lda 	#ObjectCeiling >> 8 		; embedded: the object grows up to the I/O page
		ldx 	ModeText
		cpx 	#'S'
		bne 	_PMRCeiling
		lda 	sharedCeilPage 				; shared: whichever runtime file this program will load --
_PMRCeiling:								; RTBASE for the core only, RTGPBASE with the handlers
		sec
		sbc 	newWorkspacePage
		sta 	reportValue+1
		stz 	reportValue
		jsr 	PrintDecimal
		ldx 	#FrameText & $FF
		ldy 	#FrameText >> 8
		jsr 	PrintMessage
		lda 	#FrameStackPages
		sta 	reportValue+1
		stz 	reportValue
		jsr 	PrintDecimal
		lda 	#13
		jsr 	$FFD2
		;
		;		LINES -- every line this pass read, less the lines removal left out.
		;
		ldx 	#LinesText & $FF
		ldy 	#LinesText >> 8
		jsr 	PrintMessage
		lda 	dcReads
		sta 	reportValue
		lda 	dcReads+1
		sta 	reportValue+1
		lda 	dcEnabled 					; only pass zero clears the list count, so with removal
		beq 	_PMRLinesOut 				; off it is not this compile's
		sec
		lda 	reportValue
		sbc 	dcListCount
		sta 	reportValue
		lda 	reportValue+1
		sbc 	dcListCount+1
		sta 	reportValue+1
_PMRLinesOut:
		jsr 	PrintDecimal
		lda 	#13
		jsr 	$FFD2
		;
		;		DEAD CODE -- only when dead code was being removed.
		;
		lda 	dcEnabled
		beq 	_PMREnd
		ldx 	#DeadText & $FF
		ldy 	#DeadText >> 8
		jsr 	PrintMessage
		lda 	dcListCount 				; the lines left out
		sta 	reportValue
		lda 	dcListCount+1
		sta 	reportValue+1
		lda 	#4
		jsr 	PrintDecimalField
		ldx 	#LinesRemovedText & $FF
		ldy 	#LinesRemovedText >> 8
		jsr 	PrintMessage
		lda 	dcRemovedBytes 				; ...and the bytes that saved
		sta 	reportValue
		lda 	dcRemovedBytes+1
		sta 	reportValue+1
		lda 	#4
		jsr 	PrintDecimalField
		ldx 	#BytesSavedText & $FF
		ldy 	#BytesSavedText >> 8
		jsr 	PrintMessage
		lda 	#13
		jsr 	$FFD2
_PMREnd:
		jmp 	PrintBankReport

; ************************************************************************************************
;
;								What went into the RAM banks
;
;		A LINE A BANK, AND ONLY WHEN THERE IS ONE. Most programs have no GP.BANKED or
;		GP.BANKEDSTR at all and get no bank lines, rather than a "TOTAL BANKS 0" that means
;		nothing.
;
;		ONE LAYOUT ENTRY IS ONE BANK. GPBankCheckBankFree refuses a second GP.BANKED on a bank,
;		BStrRegister refuses text on a bank a GP.BANKED owns, and BStrSelectBank keeps the text
;		banks distinct. BStrRegister enters each text bank's number in gpBankBanks too, so that
;		one table names every bank, as it names every region in the overlay file. The text
;		entries are the last bstrBankCount of the layout, in slot order (commands/gpbstrflush.asm).
;
;		USED IS WHOLE PAGES. A region is padded to a page boundary, layoutPages is the count the
;		object writer puts in the .OVL ahead of the region's bytes, and the page count is what the
;		two OVER 8K checks hold to 32 -- so FREE is room that is certainly there, and the part page
;		at the top of USED may hold a little more.
;
;		layoutCount and layoutPages are pass one's, kept for the bootstrap's table, and neither
;		pass two nor the object writer disturbs them. bstrBankCount is pass two's, which found
;		the same banks in the same order.
;
; ************************************************************************************************

PrintBankReport:
		lda 	layoutCount
		bne 	_PBRSome
		rts
_PBRSome:
		sec 								; the first text entry: GP.BANKEDSTR from here on,
		sbc 	bstrBankCount 				; GP.BANKED below it
		sta 	bankFirstText
		stz 	bankPages
		stz 	bankPages+1
		stz 	bankIndex
		;
		;		BANK nnn, and CODE or TEXT.
		;
_PBRLine:
		ldx 	#BankText & $FF
		ldy 	#BankText >> 8
		jsr 	PrintMessage
		ldx 	bankIndex
		lda 	gpBankBanks,x
		sta 	reportValue
		stz 	reportValue+1
		lda 	#3
		jsr 	PrintDecimalField
		ldx 	#BankCodeText & $FF
		ldy 	#BankCodeText >> 8
		lda 	bankIndex
		cmp 	bankFirstText
		bcc 	_PBRKind
		ldx 	#BankTextText & $FF
		ldy 	#BankTextText >> 8
_PBRKind:
		jsr 	PrintMessage
		;
		;		USED and FREE. PAGES TO BYTES IS A SHIFT OF EIGHT, so nothing is multiplied: the
		;		page count is the high byte and the low byte is zero. A bank is 32 pages.
		;
		ldx 	bankIndex
		lda 	layoutPages,x
		sta 	reportValue+1
		stz 	reportValue
		lda 	#5
		jsr 	PrintDecimalField
		ldx 	#BankUsedText & $FF
		ldy 	#BankUsedText >> 8
		jsr 	PrintMessage
		ldx 	bankIndex
		sec
		lda 	#32
		sbc 	layoutPages,x
		sta 	reportValue+1
		stz 	reportValue
		lda 	#6
		jsr 	PrintDecimalField
		ldx 	#BankFreeText & $FF
		ldy 	#BankFreeText >> 8
		jsr 	PrintMessage
		lda 	#13
		jsr 	$FFD2
		;
		;		...into the total, and on to the next entry.
		;
		ldx 	bankIndex
		clc
		lda 	layoutPages,x
		adc 	bankPages
		sta 	bankPages
		bcc 	_PBRNoCarry
		inc 	bankPages+1
_PBRNoCarry:
		inc 	bankIndex
		lda 	bankIndex
		cmp 	layoutCount
		bne 	_PBRLine
		;
		;		TOTAL BANKS -- the count of the lines above, then the bytes between them. The
		;		page sum moves up a byte as before, which is why it needs 24 bits: 127
		;		banks of 8K is 1,040,384 bytes.
		;
		ldx 	#TotalBanksText & $FF
		ldy 	#TotalBanksText >> 8
		jsr 	PrintMessage
		lda 	layoutCount
		sta 	reportValue
		stz 	reportValue+1
		jsr 	PrintDecimal
		ldx 	#BankCommaText & $FF
		ldy 	#BankCommaText >> 8
		jsr 	PrintMessage
		stz 	reportValue
		lda 	bankPages
		sta 	reportValue+1
		lda 	bankPages+1
		sta 	reportValue+2
		jsr 	PrintDecimal24
		ldx 	#BankUsedText & $FF
		ldy 	#BankUsedText >> 8
		jsr 	PrintMessage
		lda 	#13
		jmp 	$FFD2

; ************************************************************************************************
;
;		reportValue to the screen as decimal, leading zeros suppressed but always at least one
;		digit. Subtract each power of ten as many times as it goes; the count is the digit. Same
;		method as _WMFDecimal, which writes to the map FILE through IOWriteByte -- this one goes
;		to CHROUT. They are kept apart rather than sharing an indirect output vector: two tiny
;		routines are easier to be sure of than one with a mode.
;
;		PrintDecimalField takes a field width in A, up to 7, and right-aligns the number in
;		spaces. PrintDecimal is the same with no field.
;
;		TWENTY-FOUR BITS, because the banked total does not fit in sixteen: 127 banks of 8K
;		is 1,040,384 bytes. Enter at PrintDecimal with a 16 bit value in the first two bytes and
;		the third is cleared for you, which is what every caller but the bank total wants.
;
; ************************************************************************************************

PrintDecimal:
		lda 	#1 							; no field: one digit wide pads nothing
PrintDecimalField: 							; A = field width, the number right-aligned in spaces
		stz 	reportValue+2 				; the 16 bit entries: two bytes set, third assumed zero
		bra 	PrintDecimalWidth
PrintDecimal24:
		lda 	#1
PrintDecimalWidth:
		sta 	reportTemp 					; seven digit positions, so a leading zero is a space from
		lda 	#7 							; power 7 - width on. reportTemp only holds the width
		sec 								; here; the subtraction loop writes over it
		sbc 	reportTemp
		sta 	reportPadFrom
		stz 	reportLead 					; 0 while we are still dropping leading zeros
		ldx 	#0
_PDPow:
		ldy 	#48 						; '0' + number of subtractions = the digit
_PDSub:
		sec
		lda 	reportValue
		sbc 	_PDPow10L,x
		sta 	reportTemp
		lda 	reportValue+1
		sbc 	_PDPow10H,x
		sta 	reportTemp+1
		lda 	reportValue+2
		sbc 	_PDPow10B,x
		bcc 	_PDUnder 					; borrow -> this power no longer goes
		sta 	reportValue+2
		lda 	reportTemp+1
		sta 	reportValue+1
		lda 	reportTemp
		sta 	reportValue
		iny
		bra 	_PDSub
_PDUnder:
		cpy 	#48 						; a zero digit ...
		bne 	_PDEmit
		lda 	reportLead
		bne 	_PDEmit
		cpx 	reportPadFrom 				; ... is dropped while still leading, or written as a
		bcc 	_PDNext 					; space once it is inside the field
		ldy 	#' '
		bra 	_PDWrite
_PDEmit:
		lda 	#1
		sta 	reportLead
_PDWrite:
		phx
		tya
		jsr 	$FFD2 						; CHROUT makes no promise about X
		plx
_PDNext:
		inx
		cpx 	#6 							; 1000000, 100000, 10000, 1000, 100, 10
		bne 	_PDPow
		lda 	reportValue 				; the units digit is always written
		ora 	#48
		jmp 	$FFD2

_PDPow10L:
		.byte 	<1000000, <100000, <10000, <1000, <100, <10
_PDPow10H:
		.byte 	>1000000, >100000, >10000, >1000, >100, >10
_PDPow10B: 									; only the top two reach this far, but the loop reads it every
		.byte 	(1000000 >> 16) & 255, (100000 >> 16) & 255, 0, 0, 0, 0 	; time round, so all six are here

;
;		Uppercase throughout: the X16 boots in PETSCII upper/graphics, where lowercase bytes
;		come out as graphics glyphs. Same reason bumpbuild.py emits 'V' not 'v'.
;
CodeText:
		.text 	"LOW CODE ",0
FreeText:
		.text 	"LOW FREE ",0
FrameText:
		.text 	", FRAME STACK ",0
SharedText: 								; the program loads a resident runtime file
		.text 	", SHARED",0
EmbeddedText: 								; ...or carries its own
		.text 	", EMBEDDED",0
GPBasicText: 								; the GP.BASIC handlers are in: GPB.RT.nnn.BIN, or embedded whole
		.text 	" GPBASIC",0
CoreText: 									; they are not: GPC.RT.nnn.BIN, or the handler block dropped
		.text 	" CORE",0
RuntimeText:
		.text 	"RUNTIME ",0
LinesText:
		.text 	"LINES ",0
DeadText:
		.text 	"DEAD CODE: ",0
LinesRemovedText:
		.text 	" LINES REMOVED, ",0
BytesSavedText:
		.text 	" BYTES SAVED",0
BankText:
		.text 	"BANK ",0
BankCodeText:
		.text 	" CODE ",0
BankTextText:
		.text 	" TEXT ",0
BankUsedText:
		.text 	" USED",0
BankFreeText:
		.text 	" FREE",0
TotalBanksText:
		.text 	"TOTAL BANKS ",0
BankCommaText:
		.text 	", ",0

reportValue: 								; code section, not storage -- these belong to the
		.fill 	3 							; 24 bit: the banked total passes 65,535 at eight banks
reportTemp: 								; written, so they cost a compiled program nothing.
		.fill 	2 							; See the note in file-io/read.asm.
reportLead:
		.fill 	1
reportPadFrom: 								; the first power whose leading zero is a space, not dropped
		.fill 	1
bankPages: 									; pages across every bank, for the total
		.fill 	2
bankIndex: 									; the layout entry being reported
		.fill 	1
bankFirstText: 								; the first entry that is GP.BANKEDSTR text
		.fill 	1

		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		object.asm
;		Purpose:	Write object code out.
;		Created:	9th October 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;									Write object code out.
;
; ************************************************************************************************

;
;		FrameStackPages -- the gap left below the workspace for the runtime (GOSUB/FOR) stack --
;		was defined here. It now lives in common-source/source/common.inc, because the runtime
;		needs the same number to know where the bottom of that gap is (StackOpenFrame).
;

; ************************************************************************************************
;
;		Write object code out.
;
;		In memory the layout is
;
;			$0801 [ runtime ] ObjectBase [ compiler ] FreeMemory [ object code ] objPtr
;
;		but a saved program never compiles anything, so the compiler is dead weight. The
;		file is therefore written in two pieces -- the runtime, then the object code -- so
;		that on reload the object code lands at ObjectBase, on top of where the compiler was.
;
;		That reclaims (FreeMemory-ObjectBase) bytes from every compiled program, and, more
;		importantly, lets the workspace start just above the object code instead of at a
;		hardcoded $8000 -- which is most of the useable memory a compiled program gets.
;
;		The three immediates in StartCode are patched as they stream past, rather than in RAM,
;		so the copy still in memory (RUN a second time) keeps running from FreeMemory.
;
;		An embedded object has a third piece after the object code, from the next page: the bank
;		code, which StartCode copies to bank 1. See ObjReadBankCode.
;
; ************************************************************************************************

; ************************************************************************************************
;
;		HOW BIG IT IS, AND THEREFORE WHERE IT GOES. Called at the END OF PASS ONE, through
;		BLC_ENDPASS1, because pass one is where the object's length stops changing and
;		everything here follows from that length: how much of the runtime the program needs,
;		where the object code lands on reload, where the workspace starts.
;
;		PASS TWO NEEDS THE ANSWERS WHILE IT COMPILES. It was enough to work them out at the top
;		of WriteObjectCode while the finished object sat in a buffer waiting to be streamed;
;		pass two is about to write straight to the file instead, which means the file is opened
;		and the runtime written into it before pass two starts.
;
;		AND SO IS PROGRAM TOO BIG, which is the point of the exercise: a program with no room to
;		run is refused here, before a byte of it has been written, rather than after the whole
;		thing has been laid out.
;
;		Carry set = rejected, and the message has already been printed.
;
; ************************************************************************************************

PrepareObjectCode:
		lda 	ModeText 					; GPC.INPUT line 4 -- 'S' (SHARED) selects resident-runtime
		cmp 	#'S' 						; mode: emit a bootstrap + p-code, no embedded runtime
		bne 	_POCEmbedded 				; (see the shared branch below and compiler/bootstrap.asm).
		jmp 	ObjectPrepareShared 					; jmp, not a branch -- the embedded path is >127 bytes
_POCEmbedded:
		;
		;		The cut. A program using no GP.BASIC keyword takes the runtime as $0801..GPBase
		;		and puts its object code there; one that uses any takes the whole thing,
		;		$0801..ObjectBase, exactly as before. Both labels are page aligned, so a single
		;		page number says which -- and it is used THREE times below (the copy terminator,
		;		the RunCodePage patch and the workspace base), so it is settled once, here.
		;
		;		A BANKED PROGRAM ALWAYS TAKES THE WHOLE THING, gpUsed or not. GPBankRelocate
		;		corrects every branch that crosses into a bank at the END OF PASS ONE, out of the
		;		run page CompileCode handed it before the compile began -- and this cut is not
		;		settled until here, which is later. A constant is the only answer that question
		;		can have, and this is what makes it one.
		;
		;		It costs a program that banks and calls no GP.BASIC keyword the ObjectBase-GPBase
		;		bytes of handlers it will not reach. A program with 8K regions in it is not the
		;		program that grudges them, and the alternative is asking the application a question
		;		before it can answer it.
		;
		lda 	#GPBase >> 8
		ldx 	gpUsed
		bne 	_WOCCutFull
		ldx 	gpBankActive 				; ...OR IT HAS A REGION, whatever else it uses
		beq 	_WOCCutSet
_WOCCutFull:
		lda 	#ObjectBase >> 8
_WOCCutSet:
		sta 	runtimeEndPage
		;
		;		zTemp1 = length of the object code -- the LOW part of it only, measured the same way
		;		and for the same reason as ObjectPrepareShared measures it. A GP.BANKED region sits at
		;		the top of the object, page aligned, and it is not part of the image: it is appended
		;		to the .OVL beside the object and is no part of what the loader reads. Measure
		;		to objPtr instead and a hundred one-page regions read as a hundred pages of low code,
		;		which is PROGRAM TOO BIG for a program whose low code is a GOSUB and an END.
		;
		lda 	objPtr
		ldy 	objPtr+1
		ldx 	gpBankActive
		beq 	_WOCLength
		lda 	gpBankStart 				; where the regions begin -- page aligned
		ldy 	gpBankStart+1
_WOCLength:
		sec
		sbc 	#ObjectOrigin & $FF
		sta 	zTemp1
		tya
		sbc 	#ObjectOrigin >> 8
		sta 	zTemp1+1
		;
		;		Round that up to whole pages.
		;
		lda 	zTemp1 						; any part page ?
		beq 	_WOCWholePages
		inc 	zTemp1+1 					; then it needs one more
_WOCWholePages:
		;
		;		newWorkspacePage = ObjectBase + pages(object code) + the frame stack gap.
		;
		;		...and then check the program can actually RUN, which the embedded path never
		;		did -- only the SHARED path had the equivalent test. That was survivable while
		;		the compiler itself capped p-code at 12,032 bytes; with the object buffer now
		;		reaching $9EFF it is not, because a program can be compiled successfully and
		;		still leave no room above itself for variables, arrays and strings. It would
		;		load, start, and then fail in some unrelated-looking way at run time.
		;
		;		The workspace runs from newWorkspacePage to $9F00, so require MIN_WS_PAGES (4K)
		;		of it, and reject a page count that overflowed a byte on the way -- the same two
		;		tests, in the same order, as ObjectWriteShared.
		;
		clc
		lda 	runtimeEndPage 				; where the object code will actually land
		adc 	zTemp1+1
		bcs 	_WOCTooBig
		adc 	#FrameStackPages
		bcs 	_WOCTooBig
		sta 	newWorkspacePage
		cmp 	#(ObjectCeiling >> 8) - MIN_WS_PAGES + 1
		bcc 	_POCFits
_WOCTooBig:
		jmp 	ObjectTooBig 					; shared with the SHARED path: prints PROGRAM TOO BIG,
_POCFits: 									; returns carry set, caller skips the map file and OK
		jsr 	ObjPrepareOverlay 			; ...and the overlay's name and the bank it starts in
		jsr 	AsmSetBases 				; as the shared path -- see AsmCloseBlock
		jmp 	ObjStreamOpen

; ************************************************************************************************
;
;		THE OVERLAY'S NAME, AND THE BANK THE PROGRAM STARTS IN.
;
;		An embedded program's regions travel in a .OVL beside it -- the same file, in the same
;		format, that a shared program's do -- so there is no room to find for them here: they are
;		never in the object, and the workspace test above is the only ceiling the program has. What
;		the runtime image does need is the name to open and the bank to start in, and both are
;		patched into it page by page as it streams out. See _WOCImgNoOvl.
;
;		IT USED TO COUNT PAGES. An appended overlay had to fit under $9F00 together with the
;		runtime, the p-code and the workspace, and nothing but this stopped it running on into the
;		I/O page, which it did silently. A file the loader never reads has no such bound: StartCode
;		checks the bank each region asks for against the banks the machine has, one region at a
;		time, and says ?RAM.
;
;		HERE, because here is where the layout is settled and not a byte has been written yet.
;		layoutCount is pass one's, and BStrFlush has already added a region per text bank to it by
;		this point -- see SaveLayout in compiler/source/main/compiler.asm.
;
;		EMBEDDED ONLY, and it needs no test for that: the shared path left for ObjectPrepareShared
;		long before this, and pokes the same two facts into its bootstrap extension page instead --
;		see _WOCSExtName.
;
; ************************************************************************************************

ObjPrepareOverlay:
		stz 	objOvlNameLen 				; both of the runtime's answers about the overlay start at
		stz 	objStartBank 				; NONE, which is what a program with no region ships with
		lda 	layoutCount
		beq 	_OPODone 					; no regions, so no overlay and nothing to open
		jsr 	ObjBuildOverlayName 		; <object>.OVL, complete -- the image pokes nothing into it
		ldx 	ovlNameLen
		cpx 	#BXNAMEMAX+1
		bcs 	_OPONameLong
		stx 	objOvlNameLen 				; nonzero, which is also how the image knows it has an overlay
		jsr 	ObjFindStartBank 			; ...and the bank to start the program in. There is at least
		sta 	objStartBank 				; one region here, which is what that routine needs
_OPODone:
		rts

;
;		THE NAME IS BOUNDED BY THE IMAGE, as it is by the extension page in a shared build and for
;		the same reason: BXNAMEMAX bytes were set aside for it, and a longer name has nowhere to go.
;		GPC.INPUT allows 63 characters. It is the file NAME that is bounded and never the program,
;		and only a program with a region ever asks.
;
;		Compiler space, not errors.asm, for the reason _WOCSExtNameLong gives below: that table is
;		copied into every compiled program, and only a compile can ever print this.
;
_OPONameLong:
		jsr 	CallErrorHandler
		.text 	"OBJECT NAME TOO LONG FOR AN OVERLAY", 0

; ************************************************************************************************
;
;		THE BANK A PROGRAM STARTS IN, in A: the last GP.BANKED region's, which is the one a
;		program falling into a region from the line above expects. The text banks are the last
;		layout entries, one for each slot with a bank, so the regions below them are the layout
;		count less the slots in use. Not bstrBankCount, which pass two has reset and not yet
;		counted again. A program with text and no GP.BANKED region starts in its last text bank,
;		as it did before.
;
;		THE CALLER MUST HAVE ESTABLISHED THAT THERE IS A REGION. layoutCount of zero indexes
;		gpBankBanks-1 by zero, which is the byte in front of the table. Both callers ask only
;		after testing -- gpBankActive in the shared path, layoutCount in the embedded one.
;
;		ONE COPY, because both modes hand the same answer to a different reader: the shared
;		build pokes it into the bootstrap extension page, the embedded build substitutes it into
;		the runtime image at RTIMG_SBANKOFS.
;
; ************************************************************************************************

ObjFindStartBank:
		lda 	layoutCount
		ldx 	#BSTR_MAX_BANKS-1
_OSBCount:
		ldy 	bstrBankNums,x
		beq 	_OSBNext
		dec 	a
_OSBNext:
		dex
		bpl 	_OSBCount
		tax 								; the GP.BANKED regions below the text
		bne 	_OSBHave
		ldx 	layoutCount 				; none, so the last text bank
_OSBHave:
		lda 	gpBankBanks-1,x
		rts

; ************************************************************************************************
;
;		OPEN THE OBJECT FILE AND PUT THE RUNTIME IN IT -- everything that goes into the file
;		BEFORE the p-code, and all of it known by the end of pass one.
;
;		ON A LOGICAL FILE OF ITS OWN, because it stays open for the whole of pass two while the
;		source is being read on file 3. See IOOpenObject in file-io/read.asm.
;
;		Carry set = it failed, and it has said why.
;
; ************************************************************************************************

ObjStreamOpen:
		lda 	ModeText
		cmp 	#'S'
		bne 	_WOCEmbedded
		jmp 	ObjectWriteShared
_WOCEmbedded:
		;
		;		THE BANK CODE AND THE RUNTIME IMAGE ARE READ FIRST, before the object file is
		;		created. They are the two things here that can fail for a reason outside this
		;		program, and a compile that dies after creating OBJECT.PRG leaves a truncated file
		;		that looks like a program. IODeleteOutputs has already removed the old one, so
		;		failing here leaves no object at all -- the only state that cannot be mistaken for
		;		a good one.
		;
		jsr 	ObjReadBankCode 			; into its bank, to go out after the p-code
		bcs 	_WOCImgBadFar
		ldx 	#RTImageFileText & $FF
		ldy 	#RTImageFileText >> 8
		jsr 	IOOpenImage
		bcc 	_WOCImgOpened
		;
		;		Both failure paths are at the far end of this file, out of branch range from
		;		here -- the same trampoline _WOCSBigFar needs, for the same reason.
		;
_WOCImgNoneFar:
		jmp 	ObjectNoImage
_WOCImgBadFar:
		jmp 	ObjectBadImage
_WOCImgOpened:
		jsr 	IOImageIn
		jsr 	IOReadByte 					; the image's own two byte load address, which is
		bcs 	_WOCImgBadFar 				; not part of the runtime and must not be copied
		cmp 	#RTIMG_LOAD & $FF
		bne 	_WOCImgBadFar
		jsr 	IOReadByte
		bcs 	_WOCImgBadFar
		cmp 	#RTIMG_LOAD >> 8
		bne 	_WOCImgBadFar

		ldy 	#ObjectFile >> 8
		ldx 	#ObjectFile & $FF
		jsr 	IOOpenObject 				; open write, on its own logical file
		jsr 	IOSelectObject
		lda 	#1
		sta 	objStreamLive 				; from here on a failure has a file to tidy away

		lda 	#RTIMG_LOAD & $FF 			; write out the load address $0801
		jsr 	IOWriteByte
		lda 	#RTIMG_LOAD >> 8
		jsr 	IOWriteByte
		;
		;		Part one : the runtime, $0801 up to the cut, streamed from GPC.IMG.nnn.BIN and
		;		patched as it goes past. A PAGE AT A TIME, not a byte at a time: both files are
		;		open together and the KERNAL has one input channel and one output channel, so
		;		every switch between them is a CHKIN/CHKOUT pair. Per byte that is 28,000 of
		;		them; per page it is 94.
		;
		;		imgCount is the size of the chunk in hand, with ZERO MEANING 256 -- which is
		;		what makes "cpy imgCount / bne" run a full page when the counter wraps back to
		;		its start. Only the last chunk is ever short.
		;
		sec 								; imgLeft = (runtimeEndPage:00) - RTIMG_LOAD
		lda 	#0
		sbc 	#RTIMG_LOAD & $FF
		sta 	imgLeft
		lda 	runtimeEndPage
		sbc 	#RTIMG_LOAD >> 8
		sta 	imgLeft+1
		stz 	imgPage
_WOCImgChunk:
		lda 	#0 							; a whole page, unless less than one is left
		ldx 	imgLeft+1
		bne 	_WOCImgHaveN
		lda 	imgLeft
_WOCImgHaveN:
		sta 	imgCount

		jsr 	IOImageIn 					; read the chunk in
		ldy 	#0
_WOCImgRead:
		jsr 	IOReadByte
		bcs 	_WOCImgBadFar 				; the image is shorter than ObjectBase says
		sta 	imageBuffer,y
		iny
		cpy 	imgCount
		bne 	_WOCImgRead
		;
		;		The three immediates. Chunks start on page boundaries of the STREAM (the load
		;		address was consumed before the first one), so "is this offset in this chunk"
		;		is a page compare and the offset within it is the low byte. All three live in the
		;		first page in practice; the test does not assume it.
		;
		lda 	imgPage
		cmp 	#RTIMG_CODEPOFS >> 8
		bne 	_WOCImgNoCode
		ldy 	#RTIMG_CODEPOFS & $FF
		lda 	runtimeEndPage 				; object code moves down to here
		sta 	imageBuffer,y
_WOCImgNoCode:
		lda 	imgPage
		cmp 	#RTIMG_WSPAGEOFS >> 8
		bne 	_WOCImgNoWS
		ldy 	#RTIMG_WSPAGEOFS & $FF
		lda 	newWorkspacePage 			; so the workspace can start much lower
		sta 	imageBuffer,y
_WOCImgNoWS:
		lda 	imgPage
		cmp 	#RTIMG_BANKPOFS >> 8
		bne 	_WOCImgNoBank
		ldy 	#RTIMG_BANKPOFS & $FF
		sec 								; the page ObjEmitBankCode pads to, after the
		lda 	newWorkspacePage 			; p-code and below the frame stack gap
		sbc 	#FrameStackPages
		sta 	imageBuffer,y
_WOCImgNoBank:
		lda 	imgPage
		cmp 	#RTIMG_OVLLENOFS >> 8
		bne 	_WOCImgNoOvl
		ldy 	#RTIMG_OVLLENOFS & $FF
		lda 	objOvlNameLen 				; how long the .OVL's name is, 0 = no regions and no file
		sta 	imageBuffer,y
_WOCImgNoOvl:
		;
		;		AND THE NAME ITSELF, BXNAMEMAX bytes set aside for it and objOvlNameLen of them used.
		;		The shared build pokes the same name into its bootstrap extension page -- see
		;		_WOCSExtName, which is where the length is bounded for both of them.
		;
		;		IT CANNOT CROSS A CHUNK either, for the reason the table below gives, and
		;		genrtimage.py emits the .cerror that fails the build if it ever does.
		;
		lda 	imgPage
		cmp 	#RTIMG_OVLNAMOFS >> 8
		bne 	_WOCImgNoOvlName
		ldx 	objOvlNameLen
		beq 	_WOCImgNoOvlName 			; no overlay, so the template's zeros are what ships
		dex
_WOCImgOvlName:
		txa
		clc
		adc 	#RTIMG_OVLNAMOFS & $FF
		tay
		lda 	OvlFileName,x
		sta 	imageBuffer,y
		dex
		bpl 	_WOCImgOvlName
_WOCImgNoOvlName:
		lda 	imgPage
		cmp 	#RTIMG_SBANKOFS >> 8
		bne 	_WOCImgNoSBank
		ldy 	#RTIMG_SBANKOFS & $FF
		lda 	objStartBank 				; ...and the bank it starts in, 0 = leave it alone
		sta 	imageBuffer,y
_WOCImgNoSBank:
		;
		;		AND THE GP.BSTR SLOT-TO-BANK TABLE, sixteen bytes rather than one. The shared build
		;		pokes the same bytes into the bootstrap extension page (see _WOCSExtBStr); here they
		;		go into the image, and StartCode copies them to GPBSTRBANKS on the way in.
		;
		;		THE RUN CANNOT CROSS A CHUNK. 00rtimage.header aligns the table to sixteen and
		;		genrtimage.py fails the build if it straddles a page anyway, so every byte of it is
		;		in this chunk and the offset within the chunk is the low byte plus X.
		;
		lda	imgPage
		cmp	#RTIMG_BSTROFS >> 8
		bne	_WOCImgNoBStr
		ldx	#BSTR_MAX_BANKS-1
_WOCImgBStr:
		txa
		clc
		adc	#RTIMG_BSTROFS & $FF
		tay
		lda	bstrBankNums,x
		sta	imageBuffer,y
		dex
		bpl	_WOCImgBStr
_WOCImgNoBStr:
		jsr 	IOObjectOut 				; and write it out
		ldy 	#0
_WOCImgWrite:
		lda 	imageBuffer,y
		jsr 	IOWriteByte
		iny
		cpy 	imgCount
		bne 	_WOCImgWrite

		inc 	imgPage
		lda 	imgCount 					; imgLeft -= imgCount, remembering the zero
		bne 	_WOCImgSubN
		dec 	imgLeft+1 					; a whole page
		bra 	_WOCImgMore
_WOCImgSubN:
		sec
		lda 	imgLeft
		sbc 	imgCount
		sta 	imgLeft
		bcs 	_WOCImgMore
		dec 	imgLeft+1
_WOCImgMore:
		lda 	imgLeft
		ora 	imgLeft+1
		beq 	_WOCImgDone
		jmp 	_WOCImgChunk 				; out of branch range since the third patch
_WOCImgDone:
		jsr 	IOCloseImage 				; CLRCHNs, so the object file has to be reselected
		jmp 	ObjStreamReady

; ************************************************************************************************
;
;		Shared (resident-runtime) output: [$0801 bootstrap][$0900 p-code], no embedded runtime.
;		The bootstrap (compiler/bootstrap.asm) is streamed as the first 255 bytes with WS_START
;		patched in; the p-code follows and lands at $0900 on reload. A program whose p-code +
;		frame-stack gap + minimum workspace would not fit below RTBASE is rejected (carry set).
;
; ************************************************************************************************

ObjectPrepareShared:
		;
		;		p-code length -> whole pages (same as the embedded path)
		;
		;		...but only the LOW part of it. A GP.BANKED region sits at the top of the object,
		;		page aligned, and the bootstrap moves it into the bank before the runtime starts.
		;		So the workspace begins where the region begins: those bytes are in the file, and
		;		in memory for as long as it takes to copy them, and then they are workspace. That
		;		is the whole return on putting the region up there.
		;
		lda 	objPtr
		ldy 	objPtr+1
		ldx 	gpBankActive
		beq 	_WOCSLength
		lda 	gpBankStart 				; where the region ends up -- page aligned
		ldy 	gpBankStart+1
_WOCSLength:
		sec
		sbc 	#ObjectOrigin & $FF
		sta 	zTemp1
		tya
		sbc 	#ObjectOrigin >> 8
		sta 	zTemp1+1
		lda 	zTemp1
		beq 	_WOCSWhole
		inc 	zTemp1+1
_WOCSWhole:
		;
		;		WS_START = PCODE_PAGE + pages(p-code) + the frame-stack gap. Reject if that leaves
		;		fewer than MIN_WS_PAGES below RTBASE, or if the page count itself overflowed a byte.
		;
		;
		;		The workspace ends where the resident runtime starts, and that is no longer one
		;		address: a program using no GPB keyword loads the CORE-ONLY file at RTBASE and keeps
		;		everything below it, one using GPB loads the full file at RTGPBASE and stops there.
		;		2,560 bytes between them, so it is worth knowing which.
		;
		lda 	#RTBASE >> 8
		ldx 	gpUsed
		beq 	_WOCSCeiling
		lda 	#RTGPBASE >> 8
_WOCSCeiling:
		sta 	sharedCeilPage
		;
		;		AND THE WHOLE FILE HAS TO FIT UNDER IT.
		;		THE REGIONS ARE NO LONGER IN IT. They used to be -- compiled into the object,
		;		loaded at $0801 with everything else, copied up to $A000 from there -- so the file
		;		test had to count them and the workspace test did not, and the two measured
		;		different lengths. Now the regions are in a .OVL of their own, read straight into
		;		their banks, so the file ends where the low code ends, which is exactly what the
		;		workspace test already measured into zTemp1. THAT IS THE WHOLE RETURN on the
		;		overlays: a banked byte stops paying file price to arrive.
		;		overlays: a banked byte stops paying file price to arrive.
		;
		;		SO THE TEST IS NOW IMPLIED by the one below -- same length, and below adds the
		;		frame stack and a minimum workspace on top of it before comparing. It stays
		;		because it is the check that names the failure the file has, it costs a compiled
		;		program nothing, and the day something is written after the low code again it is
		;		the one that notices.
		;
		;		NOTHING REPORTED THIS AT ALL until 7th September 2026, when GPBMODS compiled clean
		;		703 bytes over and read machine code out of its own text bank -- the directory
		;		intact, the records past the overlap replaced.
		;
		lda 	zTemp1 						; the low code, which is now the whole file
		sta 	zTemp0
		lda 	zTemp1+1
		sta 	zTemp0+1
		;
		;		THE SAME BASE THE WORKSPACE IS COUNTED FROM, and it has to be: the file loads at
		;		$0801 but its p-code does not start there. PCODE_PAGE is where that lands, plus
		;		the bootstrap extension page a banked program carries -- 511 bytes of prefix in
		;		GPBMODS's case, which is two pages, which is exactly the margin this test was
		;		wrong by when it counted from page 8 instead.
		;
		clc
		lda 	#PCODE_PAGE
		adc 	gpBankActive
		adc 	zTemp0+1
		bcs 	_WOCSBigFar
		cmp 	sharedCeilPage 				; ending exactly ON the ceiling is fine: the last
		beq 	_WOCSFileFits 				; byte written is the one below it
		bcs 	_WOCSBigFar
_WOCSFileFits:
		clc
		lda 	#PCODE_PAGE
		adc 	gpBankActive 				; ...plus the bootstrap extension page, which only a
											; banked program carries. Its p-code starts at $0A00.
		adc 	zTemp1+1
		bcs 	_WOCSBigFar
		adc 	#FrameStackPages
		bcs 	_WOCSBigFar
		sta 	newWorkspacePage 			; reuse this byte to carry WS_START
		;
		;		Reject unless MIN_WS_PAGES still fit below the ceiling. Computed as a THRESHOLD and
		;		compared, rather than subtracting the ceiling from the start page: the subtraction
		;		underflows when the p-code has already run past the ceiling, and an underflow reads as
		;		a small positive gap -- i.e. it accepts exactly the programs it exists to reject.
		;
		lda 	sharedCeilPage
		sec
		sbc 	#MIN_WS_PAGES - 1 			; the highest start page that still leaves a workspace
		sta 	zTemp1 						; (the low byte is spent -- only zTemp1+1 is still live)
		lda 	newWorkspacePage
		cmp 	zTemp1
		bcs 	_WOCSBigFar
		jsr 	AsmSetBasesShared 			; GP.ASM needs both of them, and pass two needs them
		jmp 	ObjStreamOpen 				; while it compiles -- see AsmCloseBlock
;
;		ObjectTooBig is at the far end of this file, out of branch range from here -- the same
;		trampoline the embedded path needs for its image failures, for the same reason.
;
_WOCSBigFar:
		jmp 	ObjectTooBig

ObjectWriteShared:
		;
		;		Header: a normal PRG loading at $0801 -- the bootstrap sits there.
		;
		ldy 	#ObjectFile >> 8
		ldx 	#ObjectFile & $FF
		jsr 	IOOpenObject 				; open write, on its own logical file
		jsr 	IOSelectObject
		lda 	#1
		sta 	objStreamLive 				; from here on a failure has a file to tidy away
		lda 	#1
		jsr 	IOWriteByte
		lda 	#8
		jsr 	IOWriteByte
		;
		;		Part one: the bootstrap, ProgramBootstrap..ProgramBootstrapEnd, patching three operand
		;		bytes as they stream past. Build the table first -- the addresses are constants but all
		;		three VALUES are per-program, so it cannot be static data.
		;
		.set16 	BootPatchTable, ProgramBootstrap+BootWSPatchOffset
		lda 	newWorkspacePage 			; where this program's workspace starts
		sta 	BootPatchTable+2
		.set16 	BootPatchTable+3, ProgramBootstrap+BootWSEndPatchOffset
		lda 	sharedCeilPage 				; ... and where it ends: RTBASE or RTGPBASE
		sta 	BootPatchTable+5
		.set16 	BootPatchTable+6, ProgramBootstrap+BootGPPatchOffset
		lda 	gpUsed 						; ... and whether the handlers have to come with it
		beq 	_WOCSFlag
		lda 	#1 							; normalise: the bootstrap tests it with BEQ
_WOCSFlag:
		sta 	BootPatchTable+8
		;
		;		...and the three the handover needs: the p-code base page the runtime is given in
		;		A, and the two operand bytes of the closing jmp. A program with no region gets
		;		$09 and RT_ENTRY -- exactly the bytes already in the template, so patching them
		;		unconditionally costs it nothing and leaves its object byte for byte unchanged.
		;		A banked one gets $0A and $0900, which is the extension page: it does the copies
		;		and then repeats this handover itself.
		;
		.set16 	BootPatchTable+9, ProgramBootstrap+BootBasePageOffset
		clc
		lda 	#PCODE_PAGE 				; an instruction OPERAND, not a data byte
		adc 	gpBankActive
		sta 	BootPatchTable+11
		.set16 	BootPatchTable+12, ProgramBootstrap+BootRunJmpOffset
		.set16 	BootPatchTable+15, ProgramBootstrap+BootRunJmpOffset+1
		ldx 	#RT_ENTRY & $FF
		ldy 	#RT_ENTRY >> 8
		lda 	gpBankActive
		beq 	_WOCSJmpTo
		ldx 	#BootExtEntry & $FF
		ldy 	#BootExtEntry >> 8
_WOCSJmpTo:
		stx 	BootPatchTable+14
		sty 	BootPatchTable+17
		.set16 	zTemp0,ProgramBootstrap
_WOCSBoot:
		;
		;		SIX patched bytes now, not one, so the loop asks a table rather than growing a sixth
		;		copy of the same compare. Each entry is (address lo, hi, value): workspace START page,
		;		workspace END page -- which is the runtime base this program will use -- the flag
		;		saying whether it needs the GPB handlers at all, and then GP.BANKED's three.
		;
		ldx 	#0
_WOCSBootPatch:
		lda 	zTemp0
		cmp 	BootPatchTable,x
		bne 	_WOCSBootNext
		lda 	zTemp0+1
		cmp 	BootPatchTable+1,x
		bne 	_WOCSBootNext
		lda 	BootPatchTable+2,x 			; the byte to substitute
		bra 	_WOCSBootEmit
_WOCSBootNext:
		inx
		inx
		inx
		cpx 	#BootPatchEnd-BootPatchTable
		bne 	_WOCSBootPatch
		lda 	(zTemp0)
_WOCSBootEmit:
		jsr 	IOWriteByte
		inc 	zTemp0
		bne 	_WOCSBootNoHi
		inc 	zTemp0+1
_WOCSBootNoHi:
		lda 	zTemp0
		cmp 	#<ProgramBootstrapEnd
		bne 	_WOCSBoot
		lda 	zTemp0+1
		cmp 	#>ProgramBootstrapEnd
		bne 	_WOCSBoot
		;
		;		Part one and a half: the bootstrap EXTENSION page, and only for a banked program.
		;		It lands at $0900 and copies every region into its bank before handing over.
		;
		;		BUILT IN A BUFFER RATHER THAN PATCHED IN FLIGHT, unlike the bootstrap above. What
		;		goes into it is a NAME and a TABLE, neither of them one byte at an address known in
		;		advance, so the address/value list the streaming loop asks would have to be as long
		;		as the page it was writing. Copying the template into a page of compiler RAM and
		;		poking it costs the compiled program nothing.
		;
		;		imageBuffer IS THE RUNTIME IMAGE'S PAGE IN TRANSIT, and it is dead in shared mode:
		;		a shared object carries no runtime, which is the whole point of it. Same buffer,
		;		same job -- a page on its way into OBJECT.PRG.
		;
		lda 	gpBankActive
		bne 	_WOCSExtPage 				; jmp: the page is built and patched below, which the two
		jmp 	_WOCSCodePart 				; tables put out of a branch's reach
_WOCSExtPage:
		.set16 	zTemp0,ProgramBootExt
		.set16 	zTemp1,imageBuffer
		ldy 	#0 							; 256 bytes exactly, so Y wraps to end it
_WOCSExtCopy:
		lda 	(zTemp0),y
		sta 	(zTemp1),y
		iny
		bne 	_WOCSExtCopy
		;
		;		WHICH BANK EACH GP.BSTR SLOT READS ITS TEXT OUT OF -- the whole table, not the
		;		slots in use, because a slot the program never filled is zero and never read: the
		;		compiler only ever emits a slot it has filled in. Copying all of it means nothing
		;		here has to know how many there are.
		;
		;		AND THE NAME THE LOADER ASKS FOR, which with the start bank below is all this page
		;		is told about the regions. There is no bank map and no highest bank any more: the overlay
		;		file names the bank each region wants, in the order they were written, and the
		;		bootstrap reads it header by header until the end marker. See ObjBuildOverlayName.
		;
		;		BXHigh IS LEFT AT THE TEMPLATE'S ZERO, which is what it should be: it is the re-run
		;		guard now and nothing else. The page zeroes it once it has loaded the overlay, so a
		;		second RUN of the same program finds a zero and does not load it again.
		;
		ldx 	#BSTR_MAX_BANKS-1
_WOCSExtBStr:
		lda 	bstrBankNums,x
		sta 	imageBuffer+BootExtBStrOffset,x
		dex
		bpl 	_WOCSExtBStr
		;
		;		THE BANK THE PROGRAM STARTS IN, which is the last GP.BANKED region's: the one a
		;		program falling into a region from the line above expects (see BXRun). The text
		;		banks are the last layout entries, one for each slot with a bank, so the regions
		;		below them are the layout count less the slots in use. Not bstrBankCount, which
		;		pass two has reset and not yet counted again. A program with text and no
		;		GP.BANKED region starts in its last text bank, as it did before.
		;
		jsr 	ObjFindStartBank
		sta 	imageBuffer+BootExtStartBankOffset
		;
		jsr 	ObjBuildOverlayName 		; <object>.OVL, complete -- the page pokes nothing
		ldx 	ovlNameLen
		cpx 	#BXNAMEMAX+1
		bcs 	_WOCSExtNameLong
		stx 	imageBuffer+BootExtNameLenOffset
_WOCSExtName:
		dex
		lda 	OvlFileName,x
		sta 	imageBuffer+BootExtNameOffset,x
		txa
		bne 	_WOCSExtName
		bra 	_WOCSExtWrite2
;
;		THE NAME IS BOUNDED BY THE PAGE, and only here. GPC.INPUT allows 63 characters and the
;		extension page has room for BXNAMEMAX, so a longer object name has nowhere to put the
;		template the loader reads. It is the file NAME that is bounded and never the program --
;		and only a program with a region ever asks, which is why the test is here and not in the
;		name builder.
;
;		COMPILER SPACE, not errors.asm: that table links below GPBase and is copied into every
;		compiled program, so a message there would cost bytes to every program that never writes
;		a GP.BANKED. Same trick as gpasmcode.asm's _APBUnknown.
;
_WOCSExtNameLong:
		jsr 	CallErrorHandler
		.text 	"OBJECT NAME TOO LONG FOR AN OVERLAY", 0
_WOCSExtWrite2:
		ldy 	#0
_WOCSExtWrite:
		phy 								; IOWriteByte makes no promise about Y
		lda 	imageBuffer,y
		jsr 	IOWriteByte
		ply
		iny
		bne 	_WOCSExtWrite
_WOCSCodePart:
		;
		;		Part two -- the p-code itself -- follows, and pass two is what writes it.
		;
ObjStreamReady:
		lda 	#$FF 						; the image left CLRCHN behind it, so neither channel
		sta 	ioInSel 					; is known any more
		sta 	ioOutSel
		jsr 	ObjStreamReset 				; an empty buffer for pass two to fill
		clc
		rts


; ************************************************************************************************
;
;		PASS TWO WRITES THE OBJECT AS IT COMPILES IT.
;
;		THE BUFFER IS IN A BANK, and it is there for one reason: a statement that fails to
;		compile with a SYNTAX error is rolled back to where it started and a runtime throw-stub
;		is put in its place (DeferStatementToRuntime). Bytes already sent to the file cannot be
;		taken back, so nothing goes out until the statement that wrote it has compiled. Flushing
;		8K at a time also means the write channel is selected once per 8K rather than once per
;		source line, which is the same trick the runtime image already uses a page at a time.
;
;		A REGION IS A BANK OF ITS OWN. Pass two writes each GP.BANKED region straight to its
;		final address, which is ABOVE the low code it is still emitting -- so the two cannot
;		share one forward-only stream. One bank per region makes a region random access, so a
;		rollback inside one simply gets written over.
;
;		ONE SCRATCH BANK SERVES THEM ALL, and that is why the region count is not bounded by
;		banks. It used to be a bank a region, justified as costing nothing because "a region is
;		at most 8K by definition, and there are at most eight" -- which is circular: it is only
;		cheap while the count is small, and the count is what the compiler is meant to stop
;		capping. Sixteen regions took banks 8 to 23, and sixty-three would have run off the top.
;
;		ONLY ONE REGION IS EVER OPEN. regionOpen is a boolean and nextRegion a single index, and
;		gpbank.asm refuses a GP.BANKED inside an open region. Nothing writes into a region after
;		it closes either -- the exit bridge and the $FF end marker go in while the cursor is
;		still inside it, the entry bridge lands in low memory before the cursor moves, and pass
;		still inside it, the entry bridge lands in low memory before the cursor moves, and pass
;		two never goes back over what it has written. So the bank is cleared as a region opens
;		and appended to the object's one .OVL as it closes, and the next region has it.
;
;		THE OBJECT GOES OUT IN FILE ORDER: the low code and the GP.ASM pool as they are
;		compiled, then the alignment padding, then each region out of its bank. That is what
;		lets the checksum stay what it was -- a Fletcher-16 over the finished object -- with
;		pass one summing its buffer and pass two summing what it writes.
;
; ************************************************************************************************

OBJ_BUF_BANK = 7 							; the low code, waiting to go out
OBJ_RGN_BANK = 8 							; ...and the one scratch bank every region shares
OBJ_BANKCODE_BANK = 15 						; the embedded bank code, from GP1.IMG.nnn.BIN to the object
OBJ_BANKCODE_LOAD = $A000 					; ...and the address it runs at, in bank 1
OBJ_WINDOW   = $A000
OBJ_BUF_SIZE = $2000

; ************************************************************************************************
;
;		Start of pass two: an empty buffer and an empty sum. The scratch bank is NOT filled
;		here -- ObjStreamRegionFill does that as each region opens.
;
; ************************************************************************************************

ObjStreamReset:
		.set16 	objBufBase, ObjectOrigin
		.set16 	objBufTop, ObjectOrigin
		.set16 	objStmtAt, ObjectOrigin
		stz 	objHold
		rts

; ************************************************************************************************
;
;		A region is opening: clear the shared scratch bank to the padding byte. BLC_REGIONOPEN.
;
;		THE FILL IS NOT WASTE, AND IT IS PER REGION BECAUSE THE BANK IS SHARED. Above each
;		region's end marker sits filler that carries it up to a page boundary, and pass two
;		writes none of it -- there is nothing to write. Pass one's relocator fills the same bytes
;		with the same $FF, so the two objects agree. Leave the PREVIOUS region's bytes sitting
;		there and they do not, and the two-pass check reports an internal error a long way from
;		the cause.
;
; ************************************************************************************************

ObjStreamRegionFill:
		lda 	#OBJ_RGN_BANK
		jsr 	ObjStreamBank
		lda 	#OBJ_WINDOW >> 8
		sta 	zTemp0+1
		stz 	zTemp0
		lda 	#$FF
_OSRPage:
		ldy 	#0
_OSRByte:
		sta 	(zTemp0),y
		iny
		bne 	_OSRByte
		inc 	zTemp0+1
		ldx 	zTemp0+1
		cpx 	#(OBJ_WINDOW + OBJ_BUF_SIZE) >> 8
		bcc 	_OSRPage
		ldx 	objSaveBank
		stx 	CompilerRAMBankReg
		rts

; ************************************************************************************************
;
;		One object byte, in A, belonging at objPtr. Called from _CAWriteByte in pass two.
;
;		zTemp0 AND zTemp1 ARE BORROWED AND GIVEN STRAIGHT BACK. This runs between two
;		instructions of whatever generator is emitting, and they hold live pointers in both of
;		them.
;
; ************************************************************************************************

ObjStreamByte:
		sta 	objByte
		lda 	zTemp0
		pha
		lda 	zTemp0+1
		pha
		lda 	zTemp1
		pha
		lda 	zTemp1+1
		pha
		jsr 	ObjStreamWork
		pla
		sta 	zTemp1+1
		pla
		sta 	zTemp1
		pla
		sta 	zTemp0+1
		pla
		sta 	zTemp0
		rts

ObjStreamWork:
		;
		;		A statement that has armed itself: remember where it begins. Nothing from there on
		;		can go out until it has compiled, because a SYNTAX error rolls the write cursor
		;		back to it and puts a throw-stub in its place.
		;
		;		ONLY IF IT BEGINS IN THE LOW BUFFER. A region is a bank of its own and therefore
		;		random access, so a rollback inside one is written over where it stands and
		;		nothing has to be held for it -- and holding a REGION address as the low buffer's
		;		high-water mark makes the flush length a subtraction of two unrelated addresses.
		;
		lda 	deferErrors
		bne 	_OSWArming
		stz 	objHold 					; the statement compiled: nothing is held back now
		bra 	_OSWPlace
_OSWArming:
		lda 	objHold 					; already holding for this one
		bne 	_OSWPlace
		lda 	regionOpen
		bne 	_OSWPlace
		lda 	objPtr
		sta 	objStmtAt
		lda 	objPtr+1
		sta 	objStmtAt+1
		inc 	objHold
_OSWPlace:
		lda 	regionOpen 					; inside a GP.BANKED region ?
		bne 	_OSWRegion
		jsr 	ObjStreamOffset 			; where in the buffer it goes
		bcs 	_OSWLow
		jsr 	ObjStreamFlush 				; full: send out what can go, and ask again
		jsr 	ObjStreamOffset
		bcc 	_OSWLost
_OSWLow:
		lda 	#OBJ_BUF_BANK
		jsr 	ObjStreamWindow
		lda 	objByte
		sta 	(zTemp0)
		clc 								; the buffer now holds everything up to here, and a
		lda 	objPtr 						; statement rolled back lowers this with it
		adc 	#1
		sta 	objBufTop
		lda 	objPtr+1
		adc 	#0
		sta 	objBufTop+1
		bra 	_OSWClose
;
;		A single statement whose p-code is longer than the whole buffer, which no BASIC line can
;		produce: a tokenised source line is 252 bytes at most.
;
_OSWLost:
		jsr 	CallErrorHandler
		.text 	"INTERNAL ERROR OBJ LOW BUFFER", 0
;
;		Inside a region, which is a bank of its own -- random access, so a rollback here is
;		simply written over and there is nothing to hold back.
;
_OSWRegion:
		lda 	nextRegion
		asl 	a
		tax
		sec
		lda 	objPtr
		sbc 	layoutStart,x
		sta 	objBufIdx
		lda 	objPtr+1
		sbc 	layoutStart+1,x
		sta 	objBufIdx+1
		bcc 	_OSWBelow 					; the cursor wrapped past $FFFF -- the object is full
		cmp 	#OBJ_BUF_SIZE >> 8 			; past $BFFF: pass two wrote more than pass one did
		bcs 	_OSWPast
		lda 	#OBJ_RGN_BANK 				; one bank, shared -- only one region is ever open
		jsr 	ObjStreamWindow
		lda 	objByte
		sta 	(zTemp0)
_OSWClose:
		lda 	objSaveBank
		sta 	CompilerRAMBankReg
		rts

;
;		PASS TWO WROTE MORE THAN PASS ONE DID, which is the only way to get here: an oversized
;		region is stopped at the end of pass one by GPBankRelocate, and pass two is never reached.
;		The two-pass agreement check finds this too, but not until the end of the pass -- and by
;		then the stores have landed. Past 8K they go to $C000, which is ROM and discards them
;		silently; past 24K the add above wraps and they go to ZERO PAGE and low RAM, corrupting
;		the compiler that is meant to report it. Four instructions, and it says so instead.
;
;		TESTED BEFORE ObjStreamWindow, deliberately: that leaves the region's bank selected for
;		the caller to put back, and an error raised with it open would run all the way out --
;		handler, ExitCompiler, caller -- in the wrong bank. ObjStreamOffset tests in the same
;		place, for the same reason.
;
_OSWBelow:
;
;		THE OBJECT IS FULL. A region byte cannot legitimately be below its own region base, so
;		the borrow means objPtr has run off the top of sixteen bits and come back at $0000. That
;		is 65,536 bytes of low code plus regions -- see ObjectOrigin in start.asm, which is what
;		the cursor counts from.
;
;		IT HAS HAPPENED, at 37,632 bytes, when the cursor still counted from FreeMemory ($6D00).
;		GPBMODS laid its last text region at $F700 and wrapped partway through writing it: five
;		regions started at $A200 $B200 $CE00 $D800 $F700 and the sixth store came out at $0000.
;		Nothing was inconsistent between the passes -- bstrStart matched its layout entry exactly
;		-- the program had simply outgrown the counter, and this is where it showed.
;
;		SO A REAL "PROGRAM TOO BIG" BELONGS AT LAYOUT TIME, not here. Pass one knows every
;		region's base and length and could see the carry out before a byte is written, and could
;		name the region rather than an internal error four thousand lines in. This message is
;		what is left over for a cursor that got here some other way.
;
		jsr 	CallErrorHandler
		.text 	"INTERNAL ERROR OBJ REGION BELOW", 0

_OSWPast:
		jsr 	CallErrorHandler
		.text 	"INTERNAL ERROR OBJ REGION PAST 8K", 0

;
;		objBufIdx = objPtr - objBufBase, with carry set if that is inside the window.
;
ObjStreamOffset:
		sec
		lda 	objPtr
		sbc 	objBufBase
		sta 	objBufIdx
		lda 	objPtr+1
		sbc 	objBufBase+1
		sta 	objBufIdx+1
		bcc 	_OSOOut 					; below it: rolled back past what is still held
		cmp 	#OBJ_BUF_SIZE >> 8
		bcs 	_OSOOut
		sec
		rts
_OSOOut:
		clc
		rts

;
;		Select bank A, remembering the caller's, and point zTemp0 at OBJ_WINDOW + objBufIdx.
;
ObjStreamWindow:
		jsr 	ObjStreamBank
		lda 	objBufIdx
		sta 	zTemp0
		clc
		lda 	objBufIdx+1
		adc 	#OBJ_WINDOW >> 8
		sta 	zTemp0+1
		rts

ObjStreamBank:
		pha
		lda 	CompilerRAMBankReg
		sta 	objSaveBank
		pla
		sta 	CompilerRAMBankReg
		rts

; ************************************************************************************************
;
;		Send what the buffer holds to the file -- everything, or everything below the statement
;		in flight, which then moves down to the bottom of the window so the buffer is empty
;		behind it.
;
; ************************************************************************************************

ObjStreamFlush:
		lda 	objHold
		beq 	_OSFAll
		lda 	objStmtAt
		ldy 	objStmtAt+1
		bra 	_OSFTo
_OSFAll:
		lda 	objBufTop
		ldy 	objBufTop+1
_OSFTo:
		sec 								; how many bytes can go
		sbc 	objBufBase
		sta 	objFlushLen
		tya
		sbc 	objBufBase+1
		sta 	objFlushLen+1
		lda 	objFlushLen
		ora 	objFlushLen+1
		bne 	_OSFSome
		rts 								; nothing can go yet
_OSFSome:
		jsr 	IOSelectObject
		stz 	objBufIdx
		stz 	objBufIdx+1
_OSFLoop:
		lda 	objBufIdx
		cmp 	objFlushLen
		lda 	objBufIdx+1
		sbc 	objFlushLen+1
		bcs 	_OSFWritten
		lda 	#OBJ_BUF_BANK 				; the window closes again before every write: the
		jsr 	ObjStreamWindow 			; KERNAL's own buffers live in bank 0
		lda 	(zTemp0)
		ldx 	objSaveBank
		stx 	CompilerRAMBankReg
		jsr 	IOWriteByte
		inc 	objBufIdx
		bne 	_OSFLoop
		inc 	objBufIdx+1
		bra 	_OSFLoop
_OSFWritten:
		lda 	objHold 					; nothing was held back, so nothing has to move
		beq 	_OSFRebase
		sec
		lda 	objBufTop
		sbc 	objStmtAt
		sta 	objMoveLen
		lda 	objBufTop+1
		sbc 	objStmtAt+1
		sta 	objMoveLen+1
		ora 	objMoveLen
		beq 	_OSFRebase
		;
		lda 	#OBJ_BUF_BANK
		jsr 	ObjStreamBank
		clc
		lda 	objFlushLen
		sta 	zTemp0
		lda 	objFlushLen+1
		adc 	#OBJ_WINDOW >> 8
		sta 	zTemp0+1
		.set16 	zTemp1, OBJ_WINDOW
_OSFMove:
		lda 	(zTemp0)
		sta 	(zTemp1)
		inc 	zTemp0
		bne 	_OSFMSrc
		inc 	zTemp0+1
_OSFMSrc:
		inc 	zTemp1
		bne 	_OSFMDst
		inc 	zTemp1+1
_OSFMDst:
		lda 	objMoveLen
		bne 	_OSFMLow
		dec 	objMoveLen+1
_OSFMLow:
		dec 	objMoveLen
		lda 	objMoveLen
		ora 	objMoveLen+1
		bne 	_OSFMove
		lda 	objSaveBank
		sta 	CompilerRAMBankReg
_OSFRebase:
		clc
		lda 	objBufBase
		adc 	objFlushLen
		sta 	objBufBase
		lda 	objBufBase+1
		adc 	objFlushLen+1
		sta 	objBufBase+1
_OSFNone:
		rts

; ************************************************************************************************
;
;		END OF PASS TWO: everything the buffer still holds, and then the overlay file closed.
;		After this the object and its overlay are complete on disk.
;
;		THE ALIGNMENT PADDING IS GONE WITH THE REGIONS. It existed only because the regions
;		followed the low code in one file and had to start on a page boundary within it; nothing
;		follows the low code now, so there is nothing to align to. Its loop compared for EQUALITY
;		only, so a cursor that had run past layoutStart wrapped and padded forward with 65,535
;		bytes of filler, with nothing saying so. It bit twice. See
;		docs/memory/object-writer-regions-vs-low-code.md.
;
;		THE REGIONS THEMSELVES WENT OUT AT REGION CLOSE, each one while its bank still held it
;		so that the next region could have the bank. All that is left here is the CLOSE, because
;		the overlay file is opened by the first region and held open across the rest of pass two.
;		IOSelectOverlay and IOSelectSource invalidate each other on every flip, which is what
;		makes writing one output file while reading the source safe -- the trap that cost an
;		afternoon on 06/09/26 was assuming they did not.
;
; ************************************************************************************************

ObjStreamClose:
		stz 	objHold 					; nothing is in flight at the end of a compile, so the
		jsr 	ObjStreamFlush 				; flush empties the buffer -- and every region has already
											; gone out, each one as it closed
		lda 	ovlStreamLive 				; and the overlay is whole: close it, if this program had
		beq 	_OSCDone 					; any regions at all
		stz 	ovlStreamLive
		;
		;		THE END MARKER GOES ON FIRST, after the GP.BANKEDSTR text banks too -- BStrFlush has
		;		sent those out before this end-of-pass hook runs. It is what lets the loader tell a
		;		whole file from a cut one: without it the last region's last byte is end of file,
		;		and so is a file cut short on a region boundary. See BXOVLEND in bootstrap2.asm.
		;
		jsr 	IOSelectOverlay 			; the flush above left the object selected
		lda 	#BXOVLEND
		jsr 	IOWriteByte
		jmp 	IOOverlayClose
_OSCDone:
		rts

; ************************************************************************************************
;
;		The region in nextRegion is finished: work out how long it is and send it out to its own
;		overlay file. BLC_REGIONDONE, from both of the close sites.
;
;		THE SPAN IS PASS ONE'S ARITHMETIC, AND IT IS SETTLED THE WHOLE TIME. A region runs from
;		its own layoutStart to where the NEXT one starts, or to pass1Len for the topmost, and all
;		of those are known before pass two writes a byte. So this asks at region close exactly
;		what the end-of-compile loop used to ask afterwards, and gets the same answer.
;
; ************************************************************************************************

ObjEmitRegion:
		lda 	nextRegion 					; the one that has just closed
		sta 	objRgnNo
		asl 	a
		tax
		lda 	objRgnNo
		inc 	a
		cmp 	layoutCount
		bcs 	_OERTop
		lda 	layoutStart+2,x
		sta 	objSpan
		lda 	layoutStart+3,x
		sta 	objSpan+1
		bra 	_OERSpan
_OERTop:
		lda 	pass1Len
		sta 	objSpan
		lda 	pass1Len+1
		sta 	objSpan+1
_OERSpan:
		sec
		lda 	objSpan
		sbc 	layoutStart,x
		sta 	objSpan
		lda 	objSpan+1
		sbc 	layoutStart+1,x
		sta 	objSpan+1
		jmp 	ObjEmitOverlay

; ************************************************************************************************
;
;		Region objRgnNo, objSpan bytes of it, appended to <object>.OVL -- ONE overlay file for
;		the program, holding every region one after another. Each is introduced by two bytes,
;		the bank it loads into and how many pages of it follow, and the bootstrap walks the
;		file header by header until it reads the end marker ObjStreamClose puts after the last.
;		There is no directory and no length table: the file describes itself in the order it
;		is written.
;
;		PADDED UP TO THE PAGE COUNT, which is what lets the count be one byte. A region is
;		capped at 8,188 bytes, so 32 pages covers the largest, and the pad is zero for every
;		region but the topmost -- the others end where the next one starts, and that is a page
;		boundary by construction.
;
;		OPENED ONCE, BY WHICHEVER REGION CLOSES FIRST, and held open until ObjStreamClose. A
;		program with no regions therefore writes no overlay at all. Holding it open across
;		source reads is what the object file already does; IOSelectOverlay and IOSelectSource
;		invalidate each other, so the flip back to reading the source does its own CHKIN.
;
; ************************************************************************************************

ObjEmitOverlay:
		lda 	ovlStreamLive
		bne 	_OEOOpen 					; already open: this is the second region or later
		jsr 	ObjStartOverlay
_OEOOpen:
		jsr 	IOSelectOverlay
		ldx 	objRgnNo 					; THE REGION'S TWO HEADER BYTES: the bank it loads into,
		lda 	gpBankBanks,x 				; which is pass one's table and is not revalidated here
		jsr 	IOWriteByte
		ldx 	objRgnNo 					; ...and its length in PAGES. Pages to bytes is a shift of
		lda 	layoutPages,x 				; eight, so the pad target is this byte over a zero and
		sta 	objPadTop+1 				; nothing is multiplied
		stz 	objPadTop
		jsr 	IOWriteByte
		;
		stz 	objBufIdx
		stz 	objBufIdx+1
_OEOByte:
		lda 	objBufIdx
		cmp 	objSpan
		lda 	objBufIdx+1
		sbc 	objSpan+1
		bcs 	_OEOPad
		lda 	#OBJ_RGN_BANK 				; the window closes again before every write: the
		jsr 	ObjStreamWindow 				; KERNAL's own buffers live in bank 0
		lda 	(zTemp0)
		ldx 	objSaveBank
		stx 	CompilerRAMBankReg
		jsr 	IOWriteByte
		inc 	objBufIdx
		bne 	_OEOByte
		inc 	objBufIdx+1
		bra 	_OEOByte
_OEOPad:
		lda 	objBufIdx 					; and zeroes up to the page count. Only the topmost region
		cmp 	objPadTop 					; is ever short of one, so this writes nothing at all for
		lda 	objBufIdx+1 				; the rest
		sbc 	objPadTop+1
		bcs 	_OEODone
		lda 	#0
		jsr 	IOWriteByte
		inc 	objBufIdx
		bne 	_OEOPad
		inc 	objBufIdx+1
		bra 	_OEOPad
_OEODone:
		rts 								; the file stays open for the region after this one

; ************************************************************************************************
;
;		CREATE <object>.OVL, once, at the first region close.
;
;		SCRATCHED BEFORE IT IS OPENED. "name,S,W" refuses to open over a file that already
;		exists -- which is what IODeleteOutputs is for -- and quite apart from that, a stale
;		overlay beside a fresh program is the one pairing that loads, runs, and is wrong.
;
; ************************************************************************************************

ObjStartOverlay:
		jsr 	ObjBuildOverlayName
		ldx 	#OvlFileName & $FF
		ldy 	#OvlFileName >> 8
		jsr 	IOScratchFile
		ldx 	#OvlFileName & $FF
		ldy 	#OvlFileName >> 8
		jsr 	IOOpenOverlay
		lda 	#1
		sta 	ovlStreamLive 				; from here on a failure has this to tidy away too
		sta 	ovlWritten 					; ...and the embedded append has a file to look for, which it
		rts 								; still needs to know after the close at end of pass two

; ************************************************************************************************
;
;		THE EMBEDDED BANK CODE, GP1.IMG.nnn.BIN, goes after the p-code from the next page, and
;		StartCode copies it to bank 1 as the program starts. It sits in the frame stack gap and
;		the workspace, which are unused until then, and it is under MIN_WS_PAGES pages
;		(genrtimage.py checks), so PrepareObjectCode's room for the workspace is room for it.
;
;		IT IS READ INTO A BANK BEFORE THE OBJECT IS CREATED, as the image is opened first, and
;		written at BLC_CLOSEOUT. The compiler library ignores the carry from both end hooks, so
;		a file that failed there could not stop the OK.
;
;		ObjReadBankCode: carry set if the file is missing, does not load at $A000, is shorter
;		than RTIMG_BANKLEN or does not open with the embedded magic "GE". The caller's failure
;		path closes it.
;
; ************************************************************************************************

ObjReadBankCode:
		ldx 	#RTBankFileText & $FF
		ldy 	#RTBankFileText >> 8
		jsr 	IOOpenImage 				; the image's logical file, which opens after this closes
		bcs 	_ORBFail
		jsr 	IOImageIn
		jsr 	IOReadByte 					; its own load address, not part of the bank code
		bcs 	_ORBFail
		cmp 	#OBJ_BANKCODE_LOAD & $FF
		bne 	_ORBFail
		jsr 	IOReadByte
		bcs 	_ORBFail
		cmp 	#OBJ_BANKCODE_LOAD >> 8
		bne 	_ORBFail
		stz 	objBufIdx
		stz 	objBufIdx+1
_ORBByte:
		jsr 	IOReadByte
		bcs 	_ORBFail
		sta 	objByte
		lda 	#OBJ_BANKCODE_BANK
		jsr 	ObjStreamWindow
		lda 	objByte
		sta 	(zTemp0)
		lda 	objSaveBank
		sta 	CompilerRAMBankReg
		inc 	objBufIdx
		bne 	_ORBCount
		inc 	objBufIdx+1
_ORBCount:
		lda 	objBufIdx
		cmp 	#RTIMG_BANKLEN & $FF
		bne 	_ORBByte
		lda 	objBufIdx+1
		cmp 	#RTIMG_BANKLEN >> 8
		bne 	_ORBByte
		;
		lda 	#OBJ_BANKCODE_BANK 			; "GE", not the shared bank code's "GP"
		jsr 	ObjStreamBank
		lda 	OBJ_WINDOW
		ldx 	OBJ_WINDOW+1
		ldy 	objSaveBank
		sty 	CompilerRAMBankReg
		cmp 	#'G'
		bne 	_ORBFail
		cpx 	#'E'
		bne 	_ORBFail
		jsr 	IOCloseImage
		clc
		rts
_ORBFail:
		sec
		rts

;
;		BLC_CLOSEOUT, embedded only: zero bytes up to the next page, then the bank code. The two
;		passes have been compared by now, so none of it is in the checksum.
;
ObjEmitBankCode:
		lda 	ModeText
		cmp 	#'S'
		beq 	_OEBDone 					; the bootstrap loads GP1.RT.nnn.BIN instead
		jsr 	IOSelectObject
		.cerror (ObjectOrigin & $FF) != 0, "the padding counts from a low byte"
		;
		;		PAD UP TO THE PAGE THE RUNTIME WAS TOLD, which is not always the next one.
		;		RTIMG_BANKPOFS went into the image before pass two wrote a byte, out of
		;		newWorkspacePage, and newWorkspacePage came from gpBankStart -- where pass ONE put
		;		the lowest region. Pass two's low code can stop SHORT of that: BNK64's stops 1,122
		;		bytes short of it, and padding only to the next page then put the bank code four
		;		pages below where the runtime went looking for it, and the overlay with it. The
		;		program loaded, copied p-code into bank 1 as if it were the bank code, and hung.
		;
		;		THE HOLE IS ALREADY SPENT. A shared build of the same program starts its workspace
		;		above gpBankStart too, so those bytes are not free in either mode -- this only makes
		;		the FILE say what the three patched pages have been promising all along.
		;
		;		objBufBase, NOT objPtr: it is where the low code ENDS, and with GP.BANKED regions in
		;		the program those are two different addresses. The last flush of pass two leaves
		;		objBufBase one past the last byte that went into the object, while objPtr has run on
		;		up through the regions to the top of the topmost -- and the regions are not in this
		;		file.
		;
		;		A program with no region pads exactly as it always did: its newWorkspacePage was
		;		measured from objPtr, so the target IS the next page.
		;
		sec
		lda 	newWorkspacePage 			; the bank code's page, which is RTIMG_BANKPOFS...
		sbc 	#FrameStackPages
		sec
		sbc 	runtimeEndPage 				; ...counted from the p-code base, because buffer offset
		sta 	objPadLen+1 				; zero is runtimeEndPage:00 once the file is loaded
		sec
		lda 	#0 							; ...less where pass two actually stopped
		sbc 	objBufBase
		sta 	objPadLen
		lda 	objPadLen+1
		sbc 	objBufBase+1
		sta 	objPadLen+1
		bcc 	_OEBPast 					; the low code ran ABOVE its own layout, which cannot
		bra 	_OEBPadTest 				; happen and would write 64K of filler if it did
_OEBPad:
		lda 	#0
		jsr 	IOWriteByte
		lda 	objPadLen
		bne 	_OEBPadLow
		dec 	objPadLen+1
_OEBPadLow:
		dec 	objPadLen
_OEBPadTest:
		lda 	objPadLen
		ora 	objPadLen+1
		bne 	_OEBPad
_OEBPadded:
		stz 	objBufIdx
		stz 	objBufIdx+1
_OEBByte:
		lda 	#OBJ_BANKCODE_BANK 			; the window closes again before every write: the
		jsr 	ObjStreamWindow 			; KERNAL's own buffers live in bank 0
		lda 	(zTemp0)
		ldx 	objSaveBank
		stx 	CompilerRAMBankReg
		jsr 	IOWriteByte
		inc 	objBufIdx
		bne 	_OEBCount
		inc 	objBufIdx+1
_OEBCount:
		lda 	objBufIdx
		cmp 	#RTIMG_BANKLEN & $FF
		bne 	_OEBByte
		lda 	objBufIdx+1
		cmp 	#RTIMG_BANKLEN >> 8
		bne 	_OEBByte
_OEBDone:
		rts

_OEBPast:
		jsr 	CallErrorHandler
		.text 	"INTERNAL: LOW CODE ABOVE ITS OWN LAYOUT", 0

; ************************************************************************************************
;
;		BLC_CLOSEOUT, embedded only: the bank code, and then the object is done.
;
;		THE .OVL IS NOT APPENDED ANY MORE, and it is not scratched either. It stays on disk beside
;		the object, which is where the runtime image opens it -- see StartCode in 00rtimage.header.
;		An embedded program with a GP.BANKED region or a GP.BANKEDSTR group is two files now, and a
;		program with neither is still one, because no .OVL was ever created for it.
;
;		WHICH IS WHAT LIFTED THE CEILING. BASIC's LOAD reads the whole PRG into RAM before a byte of
;		the program runs, so an appended overlay had to fit under $9F00 along with the runtime, the
;		p-code and the workspace -- and the page above $9F00 is I/O, so overrunning it was silent. A
;		file the loader never reads has no such bound: the regions are limited by the banks the
;		machine has, exactly as a shared program's always were.
;
; ************************************************************************************************

ObjCloseOut:
		jsr 	ObjEmitBankCode 				; embedded: the bank code, after the p-code
		stz 	objStreamLive 				; the compile worked and the object is complete, so there
		jmp 	IOObjectClose 				; is nothing left to tidy away


; ************************************************************************************************
;
;		ObjectFile with its extension replaced by ".OVL". Modelled on SymBuildName, which does the
;		same job for the .SYM -- and like it, a name with no dot at all gets the suffix appended
;		rather than nothing.
;
;		ONE OVERLAY FILE, so there is nothing to parameterise. Every region of the program goes
;		into this one name, and the bootstrap asks for it once. It used to write the region's bank
;		as three digits and the extension page used to poke those digits per region; both halves
;		are gone.
;
;		NO LENGTH CHECK HERE. It is the extension page's TEMPLATE that the page has to hold, so
;		that is where the bound is tested -- see _WOCSExtNameLong. This buffer is CFLineSize+8
;		and a name cannot outgrow it.
;
; ************************************************************************************************

ObjBuildOverlayName:
		ldx 	#0
		ldy 	#0 							; Y = length up to and including the last dot, 0 = none
_OBONCopy:
		lda 	ObjectFile,x
		beq 	_OBONEnd
		sta 	OvlFileName,x
		cmp 	#'.'
		bne 	_OBONNext
		txa
		tay
		iny 								; keep the dot itself
_OBONNext:
		inx
		cpx 	#CFLineSize
		bne 	_OBONCopy
_OBONEnd:
		cpy 	#0
		beq 	_OBONAppend 				; no dot at all -- append ".OVL" to the whole name
		tya
		tax
		bra 	_OBONSuffix
_OBONAppend:
		lda 	#'.'
		sta 	OvlFileName,x
		inx
_OBONSuffix:
		ldy 	#0
_OBONCopySuffix:
		lda 	_OBONOvlText,y
		sta 	OvlFileName,x 				; the 0 is stored too -- ASCIIZ, for IOScratchFile
		beq 	_OBONDone 					; and IOSetFileName
		inx
		iny
		bra 	_OBONCopySuffix
_OBONDone:
		stx 	ovlNameLen 					; X stopped on the terminator, so X is the length
		rts

_OBONOvlText:
		.text 	"OVL", 0

ovlNameLen: 								; how long the name came out
		.fill 	1
ovlStreamLive: 								; nonzero while there is a half written overlay
		.fill 	1
ovlWritten: 								; nonzero once one has been created. Unlike the flag above it
		.fill 	1 							; outlives ObjStreamClose -- see ObjAppendOverlay
OvlFileName: 								; code section, like every other compiler buffer -- see
		.fill 	CFLineSize+8 				; the note in file-io/read.asm


objBufBase: 								; the objPtr of the first byte still in the buffer
		.fill 	2
objPadLen: 									; bytes of filler between the end of the low code and the
		.fill 	2 							; page the bank code was promised -- see ObjEmitBankCode
objBufTop: 									; ...and one past the last
		.fill 	2
objStmtAt: 									; where the statement in flight began
		.fill 	2
objBufIdx: 									; an offset into whichever window is open
		.fill 	2
objFlushLen: 								; how many bytes this flush is sending
		.fill 	2
objMoveLen: 								; ...and how many it is shuffling down afterwards
		.fill 	2
objSpan: 									; the region being written out
		.fill 	2
objPadTop: 									; ...and the page-rounded length it is padded up to
		.fill 	2
objByte: 									; the byte in hand, across the zTemp save
		.fill 	1
objOvlNameLen: 								; how long the name of an embedded program's .OVL is, 0 = it
		.fill 	1 							; has no regions and opens nothing -- see ObjPrepareOverlay
objStartBank: 								; ...and the bank it starts running in, 0 = none
		.fill 	1
objHold: 									; nonzero while the low buffer is holding a statement
		.fill 	1 							; back, because it might yet be rolled back
objRgnNo: 									; the region being filled or written
		.fill 	1
objSaveBank: 								; the caller's RAM bank, across a window
		.fill 	1

; ************************************************************************************************
;
;		A COMPILE THAT STOPS LEAVES NO OBJECT. The file is created before pass two starts now,
;		so a failure anywhere in pass two would otherwise leave a truncated one behind -- and at
;		the filesystem level that is indistinguishable from a program.
;
; ************************************************************************************************

ObjStreamAbort:
		;
		;		THE OVERLAY FIRST, if one was ever opened -- OvlFileName still holds its name,
		;		because ObjStartOverlay is the only thing that builds it. There is one file now
		;		rather than the one that happened to be open, so this takes away every region the
		;		compile had written, not just the last. It has to: a half written overlay is a
		;		valid prefix of a whole one, and the bootstrap reads until EOF.
		;
		lda 	ovlStreamLive
		beq 	_OSAObject
		stz 	ovlStreamLive
		jsr 	IOOverlayClose
		ldx 	#OvlFileName & $FF
		ldy 	#OvlFileName >> 8
		jsr 	IOScratchFile
_OSAObject:
		lda 	objStreamLive
		beq 	_OSADone
		stz 	objStreamLive
		jsr 	IOObjectClose
		ldx 	#ObjectFile & $FF
		ldy 	#ObjectFile >> 8
		jmp 	IOScratchFile
_OSADone:
		rts

objStreamLive: 								; nonzero while there is a half written object file
		.fill 	1
ObjectTooBig:
		ldx 	#ProgramTooBigText & $FF
		ldy 	#ProgramTooBigText >> 8
		bra 	ObjectFail

;
;		The runtime image or the bank code is missing, or is not the file its name claims. Either
;		way there is no object: both are read before OBJECT.PRG is created precisely so that this
;		leaves nothing behind. The name carries the runtime build number, so "missing" is also
;		what a stale image from an older release looks like -- which is the point of numbering
;		it rather than trusting a fixed name to be the right one.
;
ObjectBadImage: 								; missing, wrong load address, or shorter than
ObjectNoImage: 								; ObjectBase says it should be
		jsr 	ObjStreamAbort 				; the object file may already exist -- see above
		jsr 	IOCloseImage 				; CLOSE on a logical file that was never opened is
											; harmless, and the OPEN may have half-registered it.
											; Leaving it would fail the NEXT compile's open, and
											; re-RUNning the compiler is now the only way to
											; retry -- PatchOutCompile used to make a second RUN
											; run the program instead.
		ldx 	#NoRuntimeImageText & $FF
		ldy 	#NoRuntimeImageText >> 8
ObjectFail:
		jsr 	PrintMessage
		sec 								; rejected -- CompileCode skips the map file and the OK
		rts

ProgramTooBigText:
		.text 	"PROGRAM TOO BIG", 13, 0

NoRuntimeImageText:
		.text 	"NO RUNTIME IMAGE", 13, 0

; ************************************************************************************************
;
;		Write the debug MAP file, if GPC.INPUT gave a third line (its name). The map turns a
;		runtime error's "@ $XXXX" back into a source line, which is otherwise a hand decode of
;		the p-code. One text line per source line, in ascending code order:
;
;			0030 12
;
;		the 4-digit hex P-CODE OFFSET -- exactly what the runtime prints as "@ $0030" -- then a
;		space and the DECIMAL BASIC line number that begins there. To place an error, find the
;		largest offset that is <= the one reported.
;
;		ASCENDING CODE ORDER, EXCEPT AFTER A GP.BANKED. The table is walked in the order the
;		lines were marked, which is source order, and those two were the same thing until
;		GPBankRelocate started lifting a region out to the end of the object. A program with a
;		region in it has that region's lines carrying the HIGHEST offsets while still sitting
;		where they were written. Every entry is still right; the file is simply no longer
;		sorted, so the "largest offset <= the one reported" rule means reading the whole file
;		rather than reading down it. Sorting here instead would cost a sort of a 2,048 entry
;		banked table, and the reader can sort.
;
;		It is built straight from the compiler's line-number table (STRMarkLine): 4-byte entries
;		[line# lo, line# hi, addr lo, addr hi], growing DOWNWARD from compilerEndHigh:$00 to
;		lineNumberTable, walked here from the top down. Those are VIRTUAL addresses and the
;		table is two banks, so each entry is paged in through STRPageLine as it is reached. The
;		stored addr is the compile-time position in the object buffer (based at FreeMemory), so
;		offset = addr - FreeMemory -- the same number the runtime reports, because the object is
;		copied verbatim from FreeMemory to its run address. The two synthetic lines the implicit
;		-DIM prologue adds show up as line 65024 ($FE00, the end marker) and 65535 ($FFFF, the
;		prologue); they are real code positions, just not the user's.
;
; ************************************************************************************************

WriteMapFile:
		lda 	OptionsText 				; no third line -> no map asked for.
		bne 	_WMFStart
		rts
_WMFStart:
		ldy 	#OptionsText >> 8 			; open the map file for write (logical file 3, as the
		ldx 	#OptionsText & $FF 			; object write already closed).
		jsr 	IOOpenWrite
		lda 	compilerEndHigh 			; walk from the top of the table ...
		sta 	mapWalk+1
		stz 	mapWalk
_WMFLoop:
		sec 								; ... down one 4-byte entry at a time.
		lda 	mapWalk
		sbc 	#4
		sta 	mapWalk
		lda 	mapWalk+1
		sbc 	#0
		sta 	mapWalk+1
		lda 	mapWalk+1 					; stop once below the last (lowest) entry.
		cmp 	lineNumberTable+1
		bcc 	_WMFDone
		bne 	_WMFEntry
		lda 	mapWalk
		cmp 	lineNumberTable
		bcc 	_WMFDone
_WMFEntry:
		jsr 	_WMFWriteEntry
		bra 	_WMFLoop
_WMFDone:
		jmp 	IOWriteClose

;
;		Write one entry: "<hhhh> <ddddd>",CR. Everything the line needs is pulled out through
;		zTemp0 up front, before any IOWriteByte -- CHROUT to a file is free to trash zero page,
;		but mapValue/mapOff are plain RAM and survive it.
;
_WMFWriteEntry:
		lda 	mapWalk 					; mapWalk is a VIRTUAL address covering both banks of
		sta 	lineWalk 					; the table; STRPageLine points zTemp0 at the entry
		lda 	mapWalk+1 					; for real, and selects the bank it is in.
		sta 	lineWalk+1
		jsr 	STRPageLine
		;
		;		The table is in banked RAM now, so page it in for the four reads and page it back
		;		out again before any file I/O -- the KERNAL owns bank 0. That the entry is fully
		;		unpacked into mapValue/mapOff before the first IOWriteByte was already true (see
		;		the note above); it is now load-bearing rather than merely tidy.
		;
		.storage_access
		ldy 	#0 							; line number -> mapValue (consumed by the decimal print)
		lda 	(zTemp0),y
		sta 	mapValue
		ldy 	#1
		lda 	(zTemp0),y
		sta 	mapValue+1
		ldy 	#2 							; offset = stored address - FreeMemory (page aligned)
		lda 	(zTemp0),y
		sec
		sbc 	#ObjectOrigin & $FF
		sta 	mapOff
		ldy 	#3
		lda 	(zTemp0),y
		sbc 	#ObjectOrigin >> 8
		sta 	mapOff+1
		.storage_release
		lda 	mapOff+1 					; hex offset, high byte then low.
		jsr 	_WMFHexByte
		lda 	mapOff
		jsr 	_WMFHexByte
		lda 	#' '
		jsr 	IOWriteByte
		jsr 	IOWriteDecimal 				; decimal line number.
		lda 	#10 						; LF ends the line -- this file is read on the host (grep,
		jmp 	IOWriteByte 				; VS Code), not the X16, so a Unix newline suits it best.

;
;		A (0..255) as two hex digits. Same trick as the runtime error handler.
;
_WMFHexByte:
		pha
		lsr 	a
		lsr 	a
		lsr 	a
		lsr 	a
		jsr 	_WMFNibble
		pla
_WMFNibble:
		and 	#15
		cmp 	#10
		bcc 	_WMFDigit
		adc 	#6 							; carry set here: 10 -> +6+1 = 'A'
_WMFDigit:
		adc 	#48
		jmp 	IOWriteByte

;
;		mapValue (16 bit) as decimal, leading zeros suppressed but always at least one digit.
;		Subtract each power of ten as many times as it goes; the count is the digit.
;		Global, because the removed-line list (deadlist.asm) writes its numbers with it too.
;
IOWriteDecimal:
		stz 	mapLead 					; 0 while we are still dropping leading zeros
		ldx 	#0
_IWDPow:
		ldy 	#48 						; '0' + number of subtractions = the digit
_IWDSub:
		sec
		lda 	mapValue
		sbc 	_IWDPow10L,x
		sta 	mapTemp
		lda 	mapValue+1
		sbc 	_IWDPow10H,x
		bcc 	_IWDUnder 					; borrow -> this power no longer goes
		sta 	mapValue+1
		lda 	mapTemp
		sta 	mapValue
		iny
		bra 	_IWDSub
_IWDUnder:
		cpy 	#48 						; a zero digit ...
		bne 	_IWDEmit
		lda 	mapLead 					; ... is dropped while still leading
		beq 	_IWDNext
_IWDEmit:
		lda 	#1
		sta 	mapLead
		tya
		jsr 	IOWriteByte
_IWDNext:
		inx
		cpx 	#4 							; 10000, 1000, 100, 10
		bne 	_IWDPow
		lda 	mapValue 					; the units digit is always written
		ora 	#48
		jmp 	IOWriteByte

_IWDPow10L:
		.byte 	<10000, <1000, <100, <10
_IWDPow10H:
		.byte 	>10000, >1000, >100, >10

BootPatchTable: 							; six (addr lo, addr hi, value) triples, built per program
		.fill 	18 							; by the shared path just above -- see the note there.
BootPatchEnd:
sharedCeilPage: 							; page the shared workspace stops at: RTBASE normally,
		.fill 	1 							; RTGPBASE when the GPB handlers sit below it.
runtimeEndPage: 							; first page ABOVE the runtime as written out: GPBase if the
		.fill 	1 							; GP block was dropped, ObjectBase if it was kept.
imgLeft: 									; bytes of the runtime image still to copy, and which
		.fill 	2 							; page of the stream the chunk in hand came from --
imgPage: 									; the patch test is a page compare, see part one.
		.fill 	1
imgCount: 									; size of the chunk in hand, ZERO MEANING 256.
		.fill 	1
newWorkspacePage: 							; first page of workspace in the saved file. In the code
		.fill 	1 							; section, not storage -- see the note in
											; file-io/read.asm.
mapWalk: 									; these too live in the code section, not storage -- they
		.fill 	2 							; belong to the compiler and are thrown away when the
mapValue: 									; object is written, so they cost a compiled program
		.fill 	2 							; nothing. See the note in file-io/read.asm.
mapOff:
		.fill 	2
mapTemp:
		.fill 	2
mapLead:
		.fill 	1

; ************************************************************************************************
;
;		GP.ASM's fixups need BOTH bases, and neither is settled until the two paths above have
;		got this far: where the object will RUN, and where the workspace will start. Patching
;		this late is free -- nothing here changes the object's length, and the buffer is not
;		streamed out until below.
;
;		FreeMemory and newWorkspacePage are application symbols and the assembler lives in the
;		compiler library, which also builds on its own, so the arithmetic has to happen on this
;		side of the line. Both ends are page aligned, so a byte each says all of it.
;
; ************************************************************************************************

AsmSetBases:
		sec 								; embedded: it runs at runtimeEndPage, it sits at
		lda 	runtimeEndPage 				; FreeMemory, and the difference is what every blob
		sbc 	#ObjectOrigin >> 8 			; address and label target has to move by
		sta 	AsmPageDelta
		lda 	newWorkspacePage
		sta 	AsmWorkspacePage
		rts

AsmSetBasesShared:
		clc
		lda 	#(PCODE_PAGE - (ObjectOrigin >> 8)) & $FF
		adc 	gpBankActive 				; shared p-code lands at $0900, or $0A00 for a banked
		sta 	AsmPageDelta 				; program -- the extension page is below it
		lda 	newWorkspacePage 			; ObjectPrepareShared carries WS_START in this byte
		sta 	AsmWorkspacePage
		rts

;
;		One page of the runtime image, in transit from GPC.IMG.nnn.BIN to OBJECT.PRG. It is in
;		the code section, so it is compiler space and costs a compiled program nothing -- and
;		it buys back 9,818 bytes of low RAM that used to hold the whole image, so it is the
;		cheapest 256 bytes in the build.
;
imageBuffer:
		.fill 	256

		.send code

