; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		read.asm
;		Purpose:	Read file code.
;		Created:	9th October 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;								 Open sequential file for Read
; 									   YX = ASCIIZ name
;
; ************************************************************************************************

IOOpenRead:
		lda 	#'R' 						; read.
		jsr 	IOSetFileName 				; set up name/LFS
		ldx	 	#3 							; use file 3 for reading
		jsr 	$FFC6 						; CHKIN
		rts

; ************************************************************************************************
;
;			 Open the runtime image for read -- YX = ASCIIZ name, carry set if it failed
;
;		ON ITS OWN LOGICAL FILE, because it is read while OBJECT.PRG is open for write and
;		everything else here uses file 3 for both. The channel is NOT selected here: the
;		streamer alternates CHKIN/CHKOUT a page at a time, so whichever it set would be wrong
;		by the time the first byte moved.
;
; ************************************************************************************************

IO_IMAGE_FILE = 4
IO_OBJECT_FILE = 6
IO_OVL_FILE = 7 							; ...and one for the .OVL overlay file -- see below

IOOpenImage:
		lda 	#IO_IMAGE_FILE
		sta 	ioFileNo
		lda 	#'R'
		jsr 	IOSetFileName 				; carry comes back from OPEN
		ldy 	#3 							; put the default back for every other caller
		sty 	ioFileNo 					; (sty leaves the carry alone)
		rts

; ************************************************************************************************
;
;						Select the image for input / the object file for output
;
; ************************************************************************************************

IOImageIn:
		ldx 	#IO_IMAGE_FILE
		jmp 	$FFC6 						; CHKIN

IOObjectOut:
		ldx 	#IO_OBJECT_FILE
		jmp 	$FFC9 						; CHKOUT

; ************************************************************************************************
;
;		THE OBJECT FILE HAS A LOGICAL FILE OF ITS OWN, and it needs one: it is open for write
;		for the whole of pass two, while the source is open for read on file 3 and being read a
;		line at a time. Everything here used file 3 for both, which was fine while the object
;		was written after the source had been closed.
;
;		WHICH CHANNEL IS SELECTED IS REMEMBERED. The KERNAL has one input channel and one
;		output, so reading a source line and writing object bytes means switching between them
;		-- and asking for the one that is already selected is the common case by far. Two bytes
;		turn that into a compare.
;
;		$FF in either means "not known": CLRCHN, an OPEN, or anything else that goes behind
;		these routines' backs leaves them that way and the next select does the work.
;
; ************************************************************************************************

IOOpenObject:
		lda 	#IO_OBJECT_FILE
		sta 	ioFileNo
		lda 	#'W'
		jsr 	IOSetFileName 				; carry comes back from OPEN
		ldy 	#3 							; put the default back for every other caller
		sty 	ioFileNo 					; (sty leaves the carry alone)
		rts

IOObjectClose:
		lda 	#IO_OBJECT_FILE
		jsr 	$FFC3 						; CLOSE
		jsr 	$FFCC 						; CLRCHN
		lda 	#$FF
		sta 	ioInSel
		sta 	ioOutSel
		rts

; ************************************************************************************************
;
;		THE OVERLAY GETS A THIRD LOGICAL FILE, and it needs one for the same reason the object
;		does: it is written through pass two with the object still open on 6 and the source
;		still open on 3. There is one overlay file for the whole program, opened at the first
;		region close and closed at ObjStreamClose, so one file number serves it.
;
;		SELECTING IT IS NOT WORTH CACHING, unlike the object: it is selected once per region and
;		then written from end to end, so the compare would save a CHKOUT only for a program of
;		one region. What the select must do is tell the cache that the object is no longer the
;		selected output, or the object writer would skip the CHKOUT it needs on the way back.
;
; ************************************************************************************************

IOOpenOverlay:
		lda 	#IO_OVL_FILE
		sta 	ioFileNo
		lda 	#'W'
		jsr 	IOSetFileName 				; carry comes back from OPEN
		ldy 	#3 							; put the default back for every other caller
		sty 	ioFileNo 					; (sty leaves the carry alone)
		rts

IOSelectOverlay:
		lda 	#IO_OVL_FILE
		sta 	ioOutSel
		lda 	#$FF
		sta 	ioInSel
		ldx 	#IO_OVL_FILE
		jmp 	$FFC9 						; CHKOUT

IOOverlayClose:
		lda 	#IO_OVL_FILE
		jsr 	$FFC3 						; CLOSE
		jsr 	$FFCC 						; CLRCHN
		lda 	#$FF
		sta 	ioInSel
		sta 	ioOutSel
		rts

;
;		SELECTING ONE DIRECTION TAKES THE OTHER WITH IT, so each of these forgets what the
;		other knew. CHKIN and CHKOUT are not independent here: after the object file has been
;		selected for output the source is no longer selected for input, and a read that assumed
;		it still was simply stopped -- with no error and no end of file, which read as the
;		compiler hanging. It cost an afternoon on 06/09/26.
;
;		The cost is one CHKIN/CHKOUT pair per buffer flush, which is 8K of object code apart --
;		the same economy the runtime image gets by streaming a page at a time.
;
IOSelectSource:
		lda 	#3
		cmp 	ioInSel
		beq 	_IOSSDone
		sta 	ioInSel
		lda 	#$FF
		sta 	ioOutSel
		ldx 	#3
		jmp 	$FFC6 						; CHKIN
_IOSSDone:
		rts

IOSelectObject:
		lda 	#IO_OBJECT_FILE
		cmp 	ioOutSel
		beq 	_IOSODone
		sta 	ioOutSel
		lda 	#$FF
		sta 	ioInSel
		ldx 	#IO_OBJECT_FILE
		jmp 	$FFC9 						; CHKOUT
_IOSODone:
		rts
;
;		The error handler prints through CHROUT, and with the object file selected for output
;		that would put the message INTO the program being compiled.
;
IOSelectScreen:
		lda 	ioOutSel
		beq 	_IOSCDone
		stz 	ioOutSel 					; CLRCHN puts both back to the default, so neither
		lda 	#$FF 						; is known afterwards
		sta 	ioInSel
		jmp 	$FFCC 						; CLRCHN
_IOSCDone:
		rts

; ************************************************************************************************
;
;									  Close the runtime image
;
; ************************************************************************************************

IOCloseImage:
		lda 	#IO_IMAGE_FILE
		jsr 	$FFC3 						; CLOSE
		jmp 	$FFCC 						; CLRCHN -- the object file stays OPEN but stops being
											; the selected output, so IOObjectOut before writing.

; ************************************************************************************************
;
;									Read A from input file
;
;			    If read,  A=Byte and Carry Clear, else A = Error and Carry Set
;
; ************************************************************************************************

IOReadByte:
		phx 					
		phy
		jsr 	$FFB7 						; read ST
		sec
		bne 	_IORExit
		jsr 	$FFCF 						; read a byte
		clc 								; status OK.
_IORExit:		
		ply
		plx
		rts

; ************************************************************************************************
;
;							    Close files (use the same code)
;
; ************************************************************************************************

IOReadClose:
IOWriteClose:
		lda 	#3 							; CLOSE# 3
		jsr 	$FFC3
		jsr 	$FFCC 						; CLRCHN
		rts

; ************************************************************************************************
;
;				 Set LFS, Name and Open File. YX = Filename (ASCIIZ) A = R/W
;
; ************************************************************************************************

IOSetFileName:
		pha 								; save R/W
		stx 	zTemp0
		sty 	zTemp0+1
		ldy 	#$FF 						; copy name given
_IOSCopy:
		iny 								; pre-increment copy
		lda 	(zTemp0),y
		sta 	IONameBuffer,y
		bne 	_IOSCopy
		;
		pla 								; recover R/W
		cmp 	#'W'
		bne 	_IOSRead 					; reading uses the PLAIN name -- see the note below
		lda 	#',' 						; writing appends ",S,W" to create the file
		sta 	IONameBuffer+0,y
		sta 	IONameBuffer+2,y
		lda 	#'S'
		sta 	IONameBuffer+1,y
		lda 	#'W'
		sta 	IONameBuffer+3,y
		lda 	#0 							; terminator after the suffix
		sta 	IONameBuffer+4,y
		tya 								; name length plus the four we appended
		clc
		adc 	#4
		bra 	_IOSSetName
_IOSRead:
		tya 								; READ: the length is just the name -- NO ",S,R". Box16's
											; -hypercall_path opens the raw SETNAM string, so a
											; ",S,R" suffix makes it hunt for a host file literally
											; called "NAME,S,R" and the open fails. A plain name
											; reads on x16emu, Box16 and real CMDR-DOS alike (x16emu
											; only tolerated the suffix by parsing it off first).
											; Writing still needs ",S,W", which Box16 does honour.
_IOSSetName:
 								
		ldx 	#IONameBuffer & $FF			; name address to YX
		ldy 	#IONameBuffer >> 8

	    jsr 	$FFBD          				; call SETNAM

    	lda 	ioFileNo 					; set LFS to n,8,n -- n is 3 for everything except
		ldx 	#8 							; the runtime image, which has to be open for READ at
		ldy 	ioFileNo 					; the same time the object file is open for WRITE.
		jsr 	$FFBA		

		jsr 	$FFC0 						; OPEN
		rts

; ************************************************************************************************
;
;		The name, with ",S,R" or ",S,W" appended.
;
;		This was 64 bytes in the storage section, and that was a loaded gun. storage is a
;		.dsection at $0400 with the code starting at $0801 (common.inc), so it is a 1K hole --
;		and it was already full to the last byte. IONameBuffer sat at $07F1, which left it room
;		for exactly "SOURCE.PRG,S,R" and its terminator: fifteen bytes, ending at $07FF. Any
;		name longer than that would have written straight over the BASIC stub at $0801 and
;		destroyed the program that was running.
;
;		Nobody noticed because the two names were hardcoded and both were ten characters. Now
;		that GPC.INPUT supplies them, they can be any length, so the buffer is here in the code
;		section instead -- which is the compiler, above ObjectBase, thrown away when the object
;		code is written. It costs a compiled program nothing.
;
; ************************************************************************************************

ioFileNo: 									; the logical file IOSetFileName opens on. Code
		.byte 	3 							; section, like everything else here -- it is the
											; compiler's, and the compiler is thrown away.
ioInSel: 									; which file is selected for input, and which for
		.byte 	$FF 						; output. $FF = not known.
ioOutSel:
		.byte 	$FF

IONameBuffer:
		.fill 	CFLineSize+8 				; the longest line GPC.INPUT can hold, plus ",S,R"
											; and the zero
		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		start.asm
;		Purpose:	Start actual compilation.
;		Created:	9th October 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;									Compile the code from disk
;
; ************************************************************************************************

CompileCode:
		jsr 	ReadControlFile 			; GPC.INPUT says what to compile and where to put it
		bcs 	_CCNoControlFile 			; and without it there is nothing to be done
		jsr 	PrintWorking 				; which is all the compiler now says for itself
		jsr 	IODeleteOutputs 			; and clear the object AND map from a PREVIOUS run, so a
								; compile that stops on an error leaves nothing behind
		jsr 	ValidateSourceFile 			; and REFUSE ANYTHING THAT IS NOT A TOKENISED PRG.
		bcs 	_CCStopped 				; AFTER the delete, so a refused compile leaves nothing
								; behind either, and after PrintWorking, so the message
								; lands under the IN:/OUT: lines that name the file.
								; It has already said which of the two reasons it was.

		;
		;		GP.BANKED NEEDS TO KNOW WHERE THE P-CODE WILL RUN, and it needs it INSIDE the
		;		compile: pass two resolves the branches that cross into a bank as it writes them,
		;		out of corrections GPBankRelocate works out at the END OF PASS ONE -- before the
		;		application is asked anything at all. So the answer belongs here, before the
		;		compile starts, and it has to be a constant.
		;
		;		IT IS THE WHOLE BUFFER-TO-RUN PAGE DELTA. objPtr counts from ObjectOrigin and the
		;		region tables hold buffer pages, so this is what turns one into the page it runs
		;		at. GPBankRelocate used to add the bootstrap extension page to it itself, which is
		;		a layout fact and no business of the region code -- and which became wrong the
		;		moment an embedded program could have a region, because it has no such page.
		;
		;		SHARED: the bootstrap loads the p-code at PCODE_PAGE, and a banked program carries
		;		the extension page below it, so $0A00 rather than $0900.
		;
		;		EMBEDDED: the p-code runs at runtimeEndPage, which PrepareObjectCode cuts at GPBase
		;		or at ObjectBase depending on gpUsed -- and gpUsed is not final until pass one
		;		ends, which is after the corrections are wanted. So a banked embedded program is
		;		given the WHOLE runtime whatever it uses, and the delta is ObjectBase. That cut is
		;		the other half of this bargain and PrepareObjectCode says so there.
		;
		stz 	gpBankShared
		lda 	ModeText 					; GPC.INPUT line 4 -- 'S' is SHARED
		cmp 	#'S'
		bne 	_CCNotShared
		inc 	gpBankShared
_CCNotShared:
		lda 	#((ObjectBase >> 8) - (ObjectOrigin >> 8)) & $FF
		ldx 	gpBankShared
		beq 	_CCRunPage
		lda 	#(PCODE_PAGE + 1 - (ObjectOrigin >> 8)) & $FF
_CCRunPage:
		sta 	gpBankRunPage
		stz 	dcEnabled
		lda 	DeadListFile 				; GPC.INPUT line 5 -- a name turns on dead-code removal
		beq 	_CCKeepAll
		inc 	dcEnabled
_CCKeepAll:
		stz 	symCacheState 				; the first {VAR} reads the symbol file (symfile.asm)
		jsr 	GPScanReset 				; before a byte is written, because pass one decides
											; gpUsed as it writes them
		ldx 	#APIDesc & $FF
		ldy 	#APIDesc >> 8
		jsr 	StartCompiler
		bcs 	_CCStopped 					; THE COMPILE ITSELF FAILED. StartCompiler documents CC = okay
									; and CompilerErrorHandler has already printed the message and the
									; line, so there is nothing to add -- but this carry used to be
									; DROPPED, and the object was written anyway. A structure error --
									; GP.IF with no GP.ENDIF, GP.SELECT with no GP.ENDSEL, GP.EXITDO
									; with no GP.LOOP -- therefore wrote out a half-resolved object,
									; truncated at the branch it could not fix, and then printed OK.
		jsr 	WriteMapFile 				; and the line#->offset map, if GPC.INPUT asked for one
		jsr 	WriteDeadList 				; and the removed-line list, if line 5 named one
		lda 	#"O" 						; the only other thing it prints, and the only way a
		jsr 	$FFD2 						; caller can tell a compile that worked from one that
		lda 	#"K" 						; stopped on an error, so it stays.
		jsr 	$FFD2
		lda 	#' '
		jsr 	$FFD2
		jmp 	PrintMemoryReport 			; ... and what it cost -- see compiler/memreport.asm

_CCStopped: 								; either half set carry and has already said why, so stop
		jmp 	ObjStreamAbort 				; here: no object -- and the object file is created
											; before pass two now, so a half written one has to
											; be taken away -- no map file, and above all no OK.

_CCNoControlFile: 							; a compiler that guesses at what it was asked to
		jmp 	PrintNoControlFile 			; build is worse than one that refuses

; ************************************************************************************************
;
;									API Setup for the compiler
;
; ************************************************************************************************

; ************************************************************************************************
;
;		THE TWO LIMITS THAT BOUND A COMPILE.  They are separate, and conflating them is what
;		made large programs miscompile in silence.
;
;		ObjectCeiling  is how far the OBJECT CODE may grow. It is written by _CAWriteByte
;		               (api.asm) from FreeMemory upwards, and $9F00 is simply where usable low
;		               RAM stops -- the I/O page. Capacity = ObjectCeiling - FreeMemory.
;
;		CompilerWorkspace{Start,End}  is where the compiler keeps its two TABLES: the variable
;		               name list growing UP from Start, the line-number table growing DOWN from
;		               End (reset.asm). This lives in BANKED RAM at $A000-$BFFF, reached through
;		               the storage_access/storage_release macros, so it does not compete with the
;		               object code for low memory.
;
;		THEY ARE A BANK EACH, so Start..End bounds them SEPARATELY rather than jointly -- 2,048
;		lines and 1,365 variables, not 8K shared. Sharing one bank made the real limit the sum of
;		the two, and samples/edit had reached 7,981 of 8,192 (1,461 lines, 356 variables): fifty
;		more lines of source raised PROGRAM TOO BIG with a third of the OBJECT budget unused. The
;		message was right, the limit behind it was the wrong one. See x16_storage.inc.
;
;		Before this was split, the workspace started at $8000 and the object code was allowed to
;		run into it unchecked: at exactly $8000-$5100 = 12,032 bytes of p-code the object code
;		began overwriting the head of the variable name list, FindVariable then failed for EVERY
;		variable, and CreateVariableRecord handed each reference a fresh slot. The compiler
;		printed OK and emitted an object in which "X" on one line and "X" on the next were
;		different variables. samples/FSIM16_V1 (12,766 bytes of p-code) tripped it by 734 bytes.
;
; ************************************************************************************************

ObjectCeiling           = $9F00 			; embedded: the RUN address the object may grow to
ObjectOrigin            = $0000 			; ...and where objPtr counts FROM -- see below
CompilerWorkspaceStart  = $A000 			; banked RAM: variable name table, grows up
CompilerWorkspaceEnd    = $C000 			; banked RAM: line number table, grows down

; ************************************************************************************************
;
;		WHY THE OBJECT COUNTS FROM $0000 AND NOT FROM FreeMemory.
;
;		objPtr is the compile-time cursor: where the next object byte belongs. It used to start
;		at FreeMemory ($6D00) because the object was BUILT there, in low RAM, and objPtr was a
;		real address you could store through. Since the compiler went two-pass nothing is stored:
;		pass one counts and pass two streams straight to the file. So the cursor is a position in
;		the object, and every reader of it -- the map file, the memory report, the fit checks,
;		gpBankRunPage -- immediately subtracted FreeMemory again to get back to that position.
;
;		WHAT THE OLD BASE COST WAS THE TOP OF THE CURSOR. objPtr is sixteen bits and a GP.BANKED
;		or GP.BANKEDSTR region is laid out ABOVE the low code in the same counter, so the object
;		plus every region had to fit in $FFFF-$6D00 = 37,632 bytes. GPBMODS reached it: its last
;		text region was based at $F700, the cursor wrapped to $0000 partway through writing it,
;		and ObjStoreWrite raised an internal error because the byte now looked to be BELOW its
;		own region. Counting from zero gives the whole 65,536 back -- 27,904 bytes more object,
;		for the price of subtracting nothing instead of subtracting $6D00.
;
;		THIS IS NOT ObjectCeiling. That one is a RUN address and still binds: an embedded object
;		must fit below the I/O page, and a shared one below the runtime. Those checks are
;		unchanged. This constant only says where the compiler starts counting.
;
; ************************************************************************************************

APIDesc:
		.word 	CompilerAPI 				; the compiler API Implementeation
		.byte 	CompilerWorkspaceStart >> 8 	; start of workspace for compiler
		.byte 	CompilerWorkspaceEnd >> 8 		; end of workspace for compiler

;
;		The source and object file names used to be two .text constants here. They are now the
;		first two lines of GPC.INPUT -- see file-io/control.asm.
;

		.send code

		.section storage
		.send storage

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		symfile.asm
;		Purpose:	Translate a GP.ASM {VAR} name through BASLOAD's #SYMFILE.
;		Created:	30th August 2026
;
; ************************************************************************************************
; ************************************************************************************************
;
;		BASLOAD RENAMES EVERY VARIABLE. N% becomes A%, which is how it offers 64 character
;		names on a two character BASIC -- and it stores REM text byte for byte, which is the
;		very property that lets a GP.ASM body survive tokenisation at all. So {N%} in a REM
;		names a variable the compiled code no longer calls N%, and an assembly block written
;		against the source spelling would read and write a slot BASIC never touches.
;
;		#SYMFILE is BASLOAD's own answer, and it is the only one that does not change the
;		syntax: it writes source name -> crunched name for every variable and label. This
;		reads it.
;
;		THE FILE FORMAT, as BASLOAD 0.2.1 writes it:
;
;			BASLOAD 0.2.1 SYMBOL FILE
;
;			LABELS
;			------
;			FILE: PROG.BASL
;			 000076 READLINE                 =160;
;
;			VARIABLES
;			---------
;			FILE: PROG.BASL
;			 000030 PR                       =A;
;			 000031 NM                       =A0;
;
;		Two things about it matter. The LABELS section has the same line shape but its values
;		are BASIC line numbers, so the scan must not start until VARIABLES has gone past or a
;		label could answer for a variable of the same name. And THE SIGIL IS NOT RECORDED --
;		PR$ is filed as PR -- because BASLOAD crunches the identifier and the $ or % rides
;		along separately, which is exactly what lets one entry serve N, N$ and N%.
;
;		The name column is padded, but nothing here assumes its width: the name ends at the
;		first space and the value runs from the "=" to the ";".
;
;		WHERE THE FILE NAME COMES FROM. It is derived from GPC.INPUT's source line, extension
;		replaced by .SYM -- so compiling PROG.PRG reads PROG.SYM. That is the convention
;		source/gpc/build_basl.py already follows ("a #SYMFILE, if any, sits beside the PRG"),
;		and it means nothing new has to be typed or carried in GPC.INPUT. The source file has
;		to say
;
;			#SYMFILE "@:PROG.SYM"
;
;		at the top, which is where BASLOAD requires it anyway.
;
;		IT IS READ WHILE THE SOURCE FILE IS OPEN, because {VAR} is resolved mid-compile. Hence
;		its own logical file and a CHKIN back to 3 on the way out -- the compiler is part way
;		through reading a line and would otherwise carry on reading the symbol file instead.
;
;		IT IS READ ONCE A COMPILE. The first {VAR} copies every VARIABLES entry into banks 13
;		and 14 and every lookup after it searches those. Reading the file for each lookup cost
;		0.28 s of emulator time for every 10K of file ahead of the name, in every pass:
;		GPBMODS's 111 references read its 73K symbol file 222 times, 301 s of a 317 s compile.
;
;		An entry in the banks is the name, a zero, and the two bytes of the crunched name, the
;		second zero for a one character name. A zero where a name would start ends a bank.
;		Names that outgrow both banks are not an error: the lookup goes back to reading the
;		file each time.
;
; ************************************************************************************************

		.section code

IO_SYM_FILE = 5 							; 3 is the source, 4 the runtime image, 6 the object

SymCacheBank = 13 							; the first; x16_storage.inc lists every compile-time bank
SYM_CACHE_BANKS = 2 						; 16K, about 1,300 names of GPBMODS's length

SYM_UNREAD = 0 								; symCacheState: nothing read yet this compile
SYM_CACHED = 1 								; every variable is in the banks
SYM_NO_FILE = 2 							; there is no symbol file, or it is not one
SYM_TOO_BIG = 3 							; the names outgrew the banks

; ************************************************************************************************
;
;		Look AsmSymName up. CC and AsmSymCrunched set if found; CS with A=0 if there is no
;		symbol file at all and A=1 if the name is not in it.
;
; ************************************************************************************************

SymbolLookup:
		lda 	symCacheState
		bne 	_SLKnown
		jsr 	SymCacheBuild 				; the first {VAR} of the compile
		lda 	symCacheState
_SLKnown:
		cmp 	#SYM_CACHED
		bne 	_SLNotCached
		jmp 	SymCacheLookup
_SLNotCached:
		cmp 	#SYM_TOO_BIG
		bne 	_SLNoFile
		jmp 	SymFileLookup
_SLNoFile:
		lda 	#0 							; no symbol file at all -- the caller says which
		sec 								; of the two errors that is
		rts

; ************************************************************************************************
;
;		Copy every VARIABLES entry into the banks, and set symCacheState to say how that went.
;
; ************************************************************************************************

SymCacheBuild:
		lda 	#SYM_NO_FILE
		sta 	symCacheState
		jsr 	SymOpen
		bcs 	_SCBExit
		stz 	symCacheBanks
		stz 	symCachePtr 				; $C000 reads as a full bank, so the first entry
		lda 	#$C0 						; starts bank 13
		sta 	symCachePtr+1
_SCBNext:
		jsr 	SymNextVariable
		bcs 	_SCBDone
		lda 	symNameLen 					; the entry is the name and three bytes, and the
		clc 								; zero that ends the bank must fit after it
		adc 	#3
		adc 	symCachePtr
		lda 	symCachePtr+1
		adc 	#0
		cmp 	#$C0
		bcc 	_SCBStore
		lda 	symCacheBanks
		cmp 	#SYM_CACHE_BANKS
		bcs 	_SCBTooBig
		inc 	symCacheBanks
		stz 	symCachePtr
		lda 	#$A0
		sta 	symCachePtr+1
_SCBStore:
		jsr 	SymCacheStore
		bra 	_SCBNext
_SCBDone:
		lda 	#SYM_CACHED
		bra 	_SCBClose
_SCBTooBig:
		lda 	#SYM_TOO_BIG
_SCBClose:
		sta 	symCacheState
		jmp 	SymClose
_SCBExit:
		rts

; ************************************************************************************************
;
;		Write the entry SymNextVariable just read at symCachePtr, with a zero after it, and move
;		symCachePtr on to that zero. No KERNAL call while the bank is selected.
;
; ************************************************************************************************

SymCacheStore:
		lda 	symCachePtr
		sta 	zTemp0
		lda 	symCachePtr+1
		sta 	zTemp0+1
		lda 	CompilerRAMBankReg
		sta 	symSavedBank
		lda 	#SymCacheBank-1 			; symCacheBanks counts from one
		clc
		adc 	symCacheBanks
		sta 	CompilerRAMBankReg
		ldx 	symNameAt
		ldy 	#0
_SCSName:
		lda 	symLine,x
		sta 	(zTemp0),y
		inx
		iny
		cpy 	symNameLen
		bne 	_SCSName
		lda 	#0
		sta 	(zTemp0),y
		iny
		lda 	symValue
		sta 	(zTemp0),y
		iny
		lda 	symValue+1
		sta 	(zTemp0),y
		iny
		lda 	#0 							; the end of the bank, until the next entry
		sta 	(zTemp0),y
		lda 	symSavedBank
		sta 	CompilerRAMBankReg
		tya
		clc
		adc 	symCachePtr
		sta 	symCachePtr
		bcc 	_SCSExit
		inc 	symCachePtr+1
_SCSExit:
		rts

; ************************************************************************************************
;
;		Look AsmSymName up in the banks. Same result as SymbolLookup.
;
; ************************************************************************************************

SymCacheLookup:
		lda 	CompilerRAMBankReg
		sta 	symSavedBank
		ldx 	#0 							; X = bank, counting from SymCacheBank
_SCLBank:
		cpx 	symCacheBanks
		beq 	_SCLNotFound
		txa
		clc
		adc 	#SymCacheBank
		sta 	CompilerRAMBankReg
		stz 	zTemp0
		lda 	#$A0
		sta 	zTemp0+1
_SCLEntry:
		ldy 	#0
		lda 	(zTemp0),y
		beq 	_SCLNextBank 				; the zero that ends the bank
_SCLCompare:
		lda 	(zTemp0),y
		cmp 	AsmSymName,y
		bne 	_SCLSkip
		cmp 	#0 							; both names ended here
		beq 	_SCLFound
		iny
		bra 	_SCLCompare
_SCLSkip:
		lda 	(zTemp0),y 					; on to the zero after the name
		beq 	_SCLSkipped
		iny
		bra 	_SCLSkip
_SCLSkipped:
		tya 								; ...and past it and the crunched name
		clc
		adc 	#3
		adc 	zTemp0
		sta 	zTemp0
		bcc 	_SCLEntry
		inc 	zTemp0+1
		bra 	_SCLEntry
_SCLNextBank:
		inx
		bra 	_SCLBank
_SCLFound:
		iny
		lda 	(zTemp0),y
		sta 	AsmSymCrunched
		iny
		lda 	(zTemp0),y
		sta 	AsmSymCrunched+1 			; zero for a one character name
		stz 	AsmSymCrunched+2
		lda 	symSavedBank
		sta 	CompilerRAMBankReg
		clc
		rts
_SCLNotFound:
		lda 	symSavedBank
		sta 	CompilerRAMBankReg
		lda 	#1 							; there is a symbol file, the name is not in it
		sec
		rts

; ************************************************************************************************
;
;		Look AsmSymName up by reading the file from the top. Same result as SymbolLookup. Only
;		when the names did not fit the banks.
;
; ************************************************************************************************

SymFileLookup:
		jsr 	SymOpen
		bcc 	_SFLNext
		lda 	#0
		rts
_SFLNext:
		jsr 	SymNextVariable
		bcs 	_SFLNotFound
		ldx 	symNameAt
		ldy 	#0
_SFLCompare:
		lda 	symLine,x
		cmp 	AsmSymName,y
		bne 	_SFLNext
		inx
		iny
		cpy 	symNameLen
		bne 	_SFLCompare
		lda 	AsmSymName,y 				; ...and ours must end in the same place, or PR
		bne 	_SFLNext 					; would answer for PRINTER
		lda 	symValue
		sta 	AsmSymCrunched
		lda 	symValue+1
		sta 	AsmSymCrunched+1
		stz 	AsmSymCrunched+2
		jsr 	SymClose
		clc
		rts
_SFLNotFound:
		jsr 	SymClose
		lda 	#1
		sec
		rts

; ************************************************************************************************
;
;		Open the symbol file and read its banner. CC with the input channel on it; CS if there
;		is no symbol file, with nothing left open.
;
; ************************************************************************************************

SymOpen:
		jsr 	SymBuildName 				; <source>.SYM -> SymFileName
		lda 	#IO_SYM_FILE
		sta 	ioFileNo
		lda 	#'R'
		ldx 	#SymFileName & $FF
		ldy 	#SymFileName >> 8
		jsr 	IOSetFileName 				; carry comes back from OPEN
		ldy 	#3
		sty 	ioFileNo 					; put the default back for every other caller
		bcc 	_SOOpened
		rts
_SOOpened:
		ldx 	#IO_SYM_FILE
		jsr 	$FFC6 						; CHKIN
		stz 	symInVariables
		;
		;		THE OPEN TELLS YOU NOTHING. CMDR-DOS, like every CBM DOS before it, opens a file
		;		that is not there quite happily and only reports it on the first read -- so a
		;		missing symbol file arrives here looking exactly like an empty one, and would
		;		be reported as "the name is not in it" rather than "there isn't one".
		;
		;		The banner settles it: every symbol file starts "BASLOAD n.n.n SYMBOL FILE", so
		;		a first line that does not begin BASLOAD means there is no symbol file to read
		;		-- whether because it is absent, empty, or is some other file entirely.
		;
		jsr 	SymReadLine
		bcs 	_SONotSymFile
		ldx 	#0
_SOBanner:
		lda 	_SOBaslText,x
		beq 	_SOIsSymFile 				; matched the whole word
		cpx 	symLineLen
		bcs 	_SONotSymFile
		cmp 	symLine,x
		bne 	_SONotSymFile
		inx
		bra 	_SOBanner
_SOIsSymFile:
		clc
		rts
_SONotSymFile:
		jsr 	SymClose
		sec
		rts
_SOBaslText:
		.text 	"BASLOAD", 0

; ************************************************************************************************
;
;		Read on to the next VARIABLES entry. CC with its name at symLine+symNameAt, symNameLen
;		long, and its crunched name in symValue; CS at the end of the file.
;
; ************************************************************************************************

SymNextVariable:
		jsr 	SymReadLine
		bcc 	_SNVHaveLine
		rts 								; end of file, carry set
_SNVHaveLine:
		lda 	symLineLen
		beq 	SymNextVariable 			; blank
		lda 	symLine 					; a data line starts with a space, a section
		cmp 	#' ' 						; heading does not
		beq 	_SNVData
		ldx 	#0 							; is it the VARIABLES heading ?
_SNVHeading:
		lda 	_SNVVariablesText,x
		beq 	_SNVIsVariables 			; matched the whole word
		cmp 	symLine,x
		bne 	SymNextVariable 			; some other heading -- LABELS, FILE:, the banner
		inx
		bra 	_SNVHeading
_SNVIsVariables:
		lda 	#1
		sta 	symInVariables
		bra 	SymNextVariable
		;
		;		" 000030 PR                       =A;"  -- skip the space and the line number,
		;		take the name, then what lies between = and ;.
		;
_SNVData:
		lda 	symInVariables
		beq 	_SNVNextLine 				; still in LABELS, where the values are line numbers
		ldx 	#1 							; past the leading space
_SNVSkipNum:
		lda 	symLine,x
		cmp 	#' '
		beq 	_SNVAtName
		inx
		cpx 	symLineLen
		bcc 	_SNVSkipNum
		bra 	_SNVNextLine 				; malformed -- no second space
_SNVAtName:
		inx 								; first character of the name
		stx 	symNameAt
_SNVName:
		cpx 	symLineLen
		bcs 	_SNVNextLine 				; malformed -- the line ends in the name
		lda 	symLine,x
		cmp 	#' '
		beq 	_SNVNameEnd
		inx
		bra 	_SNVName
_SNVNameEnd:
		txa
		sec
		sbc 	symNameAt
		beq 	_SNVNextLine 				; malformed -- no name
		sta 	symNameLen
_SNVFindEquals:
		lda 	symLine,x
		cmp 	#'='
		beq 	_SNVAtValue
		inx
		cpx 	symLineLen
		bcc 	_SNVFindEquals
		bra 	_SNVNextLine 				; malformed -- no value
_SNVAtValue:
		inx
		stz 	symValue+1 					; a one character name leaves the second zero
		ldy 	#0
_SNVValue:
		cpx 	symLineLen
		bcs 	_SNVNextLine 				; malformed -- no ";"
		lda 	symLine,x
		cmp 	#';'
		beq 	_SNVGotValue
		cpy 	#2 							; BASLOAD crunches to one or two characters; more
		bcs 	_SNVNextLine 				; than that is not a name this BASIC could hold
		sta 	symValue,y
		iny
		inx
		bra 	_SNVValue
_SNVGotValue:
		cpy 	#0
		beq 	_SNVNextLine 				; "=;" -- nothing there
		clc
		rts
_SNVNextLine:
		jmp 	SymNextVariable 			; the head of the loop is out of branch range

_SNVVariablesText:
		.text 	"VARIABLES", 0

; ************************************************************************************************
;
;		Close the symbol file and give the source file the input channel back -- the compiler
;		is part way through reading a line and everything after this reads from it again.
;
; ************************************************************************************************

SymClose:
		lda 	#IO_SYM_FILE
		jsr 	$FFC3 						; CLOSE
		ldx 	#3
		jmp 	$FFC6 						; CHKIN the source

; ************************************************************************************************
;
;		Read one line into symLine, length in symLineLen, CS at end of file. Anything past the
;		buffer is dropped rather than wrapped -- a symbol file line is a number, a name and a
;		short value, and a longer one cannot be a variable this BASIC could hold anyway.
;
; ************************************************************************************************

SymReadLine:
		stz 	symLineLen
_SRLByte:
		jsr 	IOReadByte
		bcs 	_SRLEnd
		cmp 	#13 						; CR or LF ends it -- written on the X16, but a
		beq 	_SRLDone 					; symbol file that has been through a host tool
		cmp 	#10 						; should still read
		beq 	_SRLDone
		ldx 	symLineLen
		cpx 	#SYM_LINE_MAX
		bcs 	_SRLByte 					; over length: keep reading, stop storing
		sta 	symLine,x
		inc 	symLineLen
		bra 	_SRLByte
_SRLDone:
		clc
		rts
_SRLEnd:
		lda 	symLineLen 					; a last line with no terminator is still a line
		beq 	_SRLReallyEnd
		clc
		rts
_SRLReallyEnd:
		sec
		rts

; ************************************************************************************************
;
;		SourceFile with its extension replaced by .SYM. No extension, and .SYM is appended --
;		which is what a source called PROG (no dot) would want.
;
; ************************************************************************************************

SymBuildName:
		ldx 	#0
		ldy 	#0 							; Y = length up to and including the last dot, 0 = none
_SBNCopy:
		lda 	SourceFile,x
		beq 	_SBNEnd
		sta 	SymFileName,x
		cmp 	#'.'
		bne 	_SBNNext
		txa
		tay
		iny 								; keep the dot itself
_SBNNext:
		inx
		cpx 	#CFLineSize
		bne 	_SBNCopy
_SBNEnd:
		cpy 	#0
		beq 	_SBNAppend 					; no dot at all -- append ".SYM" to the whole name
		tya
		tax
		bra 	_SBNSuffix
_SBNAppend:
		lda 	#'.'
		sta 	SymFileName,x
		inx
_SBNSuffix:
		ldy 	#0
_SBNCopySuffix:
		lda 	_SBNSymText,y
		sta 	SymFileName,x
		beq 	_SBNDone
		inx
		iny
		bra 	_SBNCopySuffix
_SBNDone:
		rts

_SBNSymText:
		.text 	"SYM", 0

SYM_LINE_MAX = 96 							; number, name and value; the name column is padded

symLine: 									; code section, like everything else the compiler
		.fill 	SYM_LINE_MAX 				; owns -- thrown away with it, so it costs a
symLineLen: 								; compiled program nothing. See file-io/read.asm.
		.fill 	1
symInVariables: 							; past the VARIABLES heading, where the values stop
		.fill 	1 						; being line numbers and start being names
SymFileName:
		.fill 	CFLineSize+8
symNameAt: 									; the entry SymNextVariable read: where its name
		.fill 	1 						; starts in symLine, how long it is, and the
symNameLen: 								; crunched name
		.fill 	1
symValue:
		.fill 	2
symCacheState: 								; SYM_UNREAD until the first {VAR}; CompileCode
		.fill 	1 						; resets it
symCacheBanks: 								; banks holding entries, from SymCacheBank up
		.fill 	1
symCachePtr: 								; where the next entry goes
		.fill 	2
symSavedBank: 								; the caller's RAM bank, while one of ours is selected
		.fill 	1

		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
;
;	This file is automatically generated by scripts/bumpbuild.py
;
BuildNumber = 124
		.section code
VersionText:
		.text	'V1.1.0',13,0
RTImageFileText:
		.text	'GPC.IMG.124.BIN',0
RTBankFileText:
		.text	'GP1.IMG.124.BIN',0
		.send code
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		write.asm
;		Purpose:	Write file code
;		Created:	9th October 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;								Open sequential file for Write.
; 									   YX = ASCIIZ name
;
; ************************************************************************************************

IOOpenWrite:
		lda 	#'W'			 			; write
		jsr 	IOSetFileName 				; set up name/LFS
		ldx	 	#3 							; use file 3 for writing
		jsr 	$FFC9 						; CHKOUT
		rts

; ************************************************************************************************
;
;									Write A to output file
;
; ************************************************************************************************

IOWriteByte:		
		pha
		phx
		phy
		jsr 	$FFD2
		ply
		plx
		pla
		rts

; ************************************************************************************************
;
;				Delete the object file and its map, before the compile starts
;
;		WriteObjectCode only ever creates the file on SUCCESS, so a compile that stops on an
;		error leaves whatever was there before -- and a stale object from an earlier run is
;		indistinguishable from a fresh one at the filesystem level, and it RUNS. "OK" is the
;		only signal a caller gets that the compile worked; nothing about the file itself says
;		so. Clearing it up front makes a failed compile leave NO object at all, which is the
;		only state that cannot be mistaken for a good one.
;
;		Done through the DOS command channel -- "S0:<name>" on 15,8,15. The status is
;		deliberately NOT read: FILE NOT FOUND is the normal case on a first compile, and there
;		is nothing useful to do about any other outcome either, since the compile has not
;		happened yet and WriteObjectCode reports its own failures.
;
; ************************************************************************************************

IODeleteOutputs:
		ldx 	#ObjectFile & $FF 			; the object itself, always
		ldy 	#ObjectFile >> 8
		jsr 	IOScratchFile
		;
		;		And the debug map, if GPC.INPUT line 3 asked for one -- WriteMapFile keys off the
		;		same first byte. It is not runnable, so it cannot be mistaken for a program, but a
		;		map left over from an earlier run describes an object that no longer exists: every
		;		line-number-to-offset entry in it is wrong, and it is read by a debugger that has
		;		no way to tell. The two files are written together and they go together.
		;
		lda 	OptionsText
		beq 	_IODONoMap
		ldx 	#OptionsText & $FF
		ldy 	#OptionsText >> 8
		jsr 	IOScratchFile
_IODONoMap:
		;
		;		And the removed-line list, if GPC.INPUT line 5 names one. A list left from an
		;		earlier run names the lines of a program that has since changed.
		;
		lda 	DeadListFile
		beq 	_IODONoList
		ldx 	#DeadListFile & $FF
		ldy 	#DeadListFile >> 8
		jsr 	IOScratchFile
_IODONoList:
		;
		;		And the overlay. It is one file with a name that follows from the object's, so
		;		unlike the .nnn files it replaced it can be named here, before the source has been
		;		read and before anything knows whether this program has regions at all. A compile
		;		with no GP.BANKED writes none, and this is what takes away the one an earlier
		;		compile of the same source left behind.
		;
		jsr 	ObjBuildOverlayName
		ldx 	#OvlFileName & $FF
		ldy 	#OvlFileName >> 8
		jsr 	IOScratchFile
_IODODone:
		rts

;
;		AND STILL NOT BY WILDCARD, which is worth writing down because the rule outlived the
;		problem that made it necessary.
;
;		While every region had a .nnn file of its own, the only sweep that could reach them all
;		was a wildcard: which banks a source asks for is not known until it has been read. While
;		those files were .Bnn that sweep was "S0:<object>.B*", and IT SCRATCHED THE SOURCE. CBM
;		pattern matching is a prefix and a "*", so "BANKA.B*" matched BANKA.BASL as squarely as
;		BANKA.B05, and building it destroyed seventeen test sources on 08/09/26.
;
;		ONE .OVL RETIRES THE QUESTION. Its name follows from the object's, so it is known before
;		the source is read and it is deleted above by that exact name. There is no orphan left
;		to chase either: a region that changes its bank or goes away changes the contents of the
;		same file, not which files exist.
;
;		THE RULE STANDS ANYWAY. A wildcard does not go through IOScratchFile: it has no undo and
;		reads no status, so nothing here can tell what it took. See
;		docs/memory/wildcard-scratch-eats-the-source.md.
;

; ************************************************************************************************
;
;								Scratch one file.  YX = ASCIIZ name
;
; ************************************************************************************************

IOScratchFile:
		stx 	zTemp0
		sty 	zTemp0+1
		;
		;		REFUSE if the name IS the source name. A misconfigured GPC.INPUT would otherwise
		;		destroy the source before the compile had read a byte of it, and the compiler
		;		would then report a missing file rather than the mistake that caused it.
		;
		ldy 	#0
_IOSFSame:
		lda 	(zTemp0),y
		cmp 	SourceFile,y
		bne 	_IOSFDiffer
		tax 								; matched to a shared terminator -> the same name
		beq 	_IOSFDone
		iny
		bra 	_IOSFSame
_IOSFDiffer:
		lda 	#'S' 						; build "S0:<name>" -- the DOS scratch command
		sta 	IONameBuffer+0
		lda 	#'0'
		sta 	IONameBuffer+1
		lda 	#':'
		sta 	IONameBuffer+2
		ldy 	#$FF
_IOSFCopy:
		iny 								; pre-increment copy, as IOSetFileName does
		lda 	(zTemp0),y
		sta 	IONameBuffer+3,y
		bne 	_IOSFCopy
		;
		tya 								; length is the name plus the three we prefixed
		clc
		adc 	#3
		ldx 	#IONameBuffer & $FF
		ldy 	#IONameBuffer >> 8
		jsr 	$FFBD 						; SETNAM
		lda 	#15 						; SETLFS 15,8,15 -- the command channel, so OPEN is
		ldx 	#8 							; what actually sends the command
		ldy 	#15
		jsr 	$FFBA
		jsr 	$FFC0 						; OPEN
		lda 	#15
		jsr 	$FFC3 						; CLOSE
		jsr 	$FFCC 						; CLRCHN -- leave I/O where the compile expects it
_IOSFDone:
		rts

		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
